/// key = 中文原文（与源码逐字一致），value = 日语。
///
/// 由 install/i18n/gen-tables.mjs 生成，可手改（改完跑 check-tables 复核）。
const Map<String, String> kJaTable = <String, String>{
  '\n请帮我创建一个 DSH 技能，直接落盘，不要只给示例。\n\n要求：\n1. 用你的 write 工具创建文件：{0}/<技能名>/SKILL.md\n2. <技能名> 必须匹配 ^[a-z0-9]+(?:-[a-z0-9]+)\$（小写字母/数字/连字符），这是 DSH 的技能名规范。\n3. 文件内容严格是下面这个格式（frontmatter 只有 name 与 description）：\n---\nname: <技能名>\ndescription: "<一句话说明什么时候该用这个技能>"\n---\n\n<技能正文：可执行的步骤、注意事项、输出格式；Markdown>\n4. 技能主题由你根据下面的描述来定，正文要具体到能照着做，不要写空话。\n5. 写完后告诉我：技能名、文件绝对路径、以及一句话说明它解决什么问题。\n\n我想让这个技能做的事：\n（在这里把你的需求写清楚，例如：把每天的聊天记录整理成一份 Markdown 日报，带待办清单）\n': '\nDSH のスキルを作成してください。ファイルに直接書き出し、サンプルだけを見せるのは不可です。\n\n要件：\n1. write ツールで次のファイルを作成：{0}/<スキル名>/SKILL.md\n2. <スキル名> は ^[a-z0-9]+(?:-[a-z0-9]+)\\\$（小文字英数字／ハイフン）に一致すること。これが DSH のスキル名規則です。\n3. ファイルの内容は厳密に次の形式（frontmatter は name と description のみ）：\n---\nname: <スキル名>\ndescription: "<このスキルをいつ使うかを一言で>"\n---\n\n<スキル本文：実行できる手順、注意点、出力形式；Markdown>\n4. スキルのテーマは下の説明から判断し、本文はそのまま実行できる具体性で。空論は書かないこと。\n5. 完了したら教えてください：スキル名、ファイルの絶対パス、それが何を解決するかの一言。\n\nこのスキルでやりたいこと：\n（ここに要望を具体的に。例：毎日のチャットログを Markdown の日報にまとめ、TODO リスト付きにする）\n',
  '  - {0}（{1} 个成员）': '  - {0}（{1} 人）',
  '  - {0}（{1}）· 模型 {2} 个 · Key：{3}': '  - {0}（{1}）· モデル {2} 個 · Key：{3}',
  '  （没有配置任何厂家）': '  （プロバイダーが設定されていません）',
  ' · 内置': ' · 内蔵',
  ' · 内置（免费档）': ' · 内蔵（無料枠）',
  ' · 含本次运行': ' · 今回の実行を含む',
  '**在图上直接选**：按在空白处拖动 = 拉出一个新框（放哪、多大都随你）；按在框里拖动 = 整块移动；拖**四个角**的圆点 = 改大小。下面这几个只是"一键放好"的快捷起点。': '**画像上で直接選べます**：何もない所をドラッグ＝新しい枠を引き出す（位置も大きさも自由）、枠の中をドラッグ＝枠ごと移動、**四隅**の丸をドラッグ＝大きさ変更。下の項目は「ワンタップで置く」ための出発点です。',
  '**排版不用你操心**：你只说讲什么、想做成哪种样子，脚本自己算字号、分栏与分页（放不下会缩字号、再放不下会拆成「（续）」页）。产物是真正的 .pptx —— 原生形状，在 WPS / Office 里能改颜色、改字。下面是几个起点，点一个就开始（会话里再改成你要的）。': '**レイアウトは気にしなくて大丈夫**：何を話すか、どんな見せ方にしたいかだけ伝えてください。文字サイズ・段組み・改ページはスクリプトが計算します（入りきらない時はまず文字を縮め、それでも無理なら「（続き）」ページに分割）。出力は本物の .pptx（ネイティブ図形）で、WPS / Office で色も文字も変更できます。下の出発点を選んで始めてください（セッションで調整できます）。',
  '**这条通道不需要你填任何 Key** —— 它就是给"不想配 Key"准备的：打开后模型列表里会出现「免费模型（无需 Key）」这一组，直接用就行。\n\n内容由 [pollinations.ai](https://pollinations.ai) 的**匿名层**提供（它自己就是这么开放的：不用注册、不用 Key），不是我们绕出来的。': '**この経路は Key の入力が一切不要です** —— 「Key を設定したくない」人のためのものです。オンにすると、モデル一覧に「無料モデル（Key 不要）」というグループが現れ、そのまま使えます。\n\nモデルは [pollinations.ai](https://pollinations.ai) の**匿名レイヤー**から提供されます（同サービス自身が「登録不要・Key 不要」として公開しているもので、当アプリが制限を回避しているわけではありません）。',
  '+ 新建轮换池': '+ ローテーションプールを新規作成',
  '321 名专家 / 22 个分区（来自专家库）。开启某位专家后，他的摘要会写进 AGENTS.md，DSH 会在每个新会话的第一个请求前注入模型上下文 ——**会占上下文**，所以别一次开太多。': '321 名の専門家 / 22 分区（専門家ライブラリより）。専門家を有効にすると、その要約が AGENTS.md に書き込まれ、DSH が新しいセッションの最初のリクエスト前にモデルのコンテキストへ注入します —— **コンテキストを消費する**ので、一度に多くを有効にしないでください。',
  '44 种图型（架构 / 流程 / 时序 / ER / 时间线 / 桑基 / 甘特…）。产物是**自包含的网页**（HTML + 内联 SVG），画完能在「资料库」里直接打开看。下面点一个例子就开始（会话里再改成你要的）。': '44 種類の図（アーキテクチャ／プロセス／シーケンス／ER／タイムライン／サンキー／ガント…）。出力は**自己完結の Web ページ**（HTML + インライン SVG）で、描けたら「ライブラリ」でそのまま開けます。下の例をタップして始めてください（セッションで書き換えられます）。',
  '6 位数字，120 秒内有效': '6 桁の数字、120 秒間有効',
