  'ACP 的 session/resume 只恢复会话本身（模型上下文仍然在），但 DSH 要求工作目录与建会话时**完全一致**才允许恢复。': 'ACP の session/resume はセッション自体だけを復元します（モデルのコンテキストはそのまま残っています）が、DSH はセッション作成時と**完全に同じ**作業ディレクトリでないと復元を許可しません。',
  'AI 能力': 'AI 機能',
