  'API Key 已自动脱敏（会变成 ***已脱敏***），**不会**包含你的 Key。': 'APIキーは自動でマスクされます（***マスク済み*** になります）。あなたの Key は**含まれません**。',
  'API Key 无效或没填。请回设置页检查 Key，并确认它属于当前选中的服务商。': 'APIキーが無効か未入力です。設定画面に戻って Key を確認し、現在選択中のプロバイダーのものか確かめてください。',
