  'Agnes API Key（在 platform.agnes-ai.cn 创建，sk- 开头）': 'Agnes APIキー（platform.agnes-ai.cn で作成、sk- で始まる）',
  'Agnes 官方当前把这几个模型标为免费：文本 agnes-3.0-flash、图像 agnes-image-2.5-flash（官方原文：所有输出分辨率档位与输入参考图片当前均免费）、视频 agnes-video-2.5-flash（官方原文：原价 ¥0.15/秒，现价 ¥0/秒）。这是**限时/当前**的优惠价，官方注明"免费政策如有调整，以平台最新公告为准"，不要当成永久免费无限量。': 'Agnes は現在、次のモデルを無料としています：テキスト agnes-3.0-flash、画像 agnes-image-2.5-flash（公式原文：すべての出力解像度と入力参照画像は現在無料）、動画 agnes-video-2.5-flash（公式原文：通常 ¥0.15/秒、現在 ¥0/秒）。これは**期間限定／現時点**の優待価格です。公式は「無料ポリシーに変更がある場合はプラットフォームの最新告知が優先」と明記しているので、永久に無料で無制限とは考えないでください。',
  'Agnes 官方端点：文本、图像、视频共用一个 Key（图形/视频的端口是内置的，不用你配），官方当前把这几个模型标为免费（限时优惠，以平台公告为准）。适合想先零成本试一下模型好不好用的人。': 'Agnes 公式エンドポイント：テキスト・画像・動画で Key は共通です（画像／動画のエンドポイントは内蔵で、設定不要）。公式は現在これらのモデルを無料としています（期間限定、プラットフォームの告知が優先）。まず無料でモデルを試してみたい人向け。',
  'Agnes 文生图（当前免费）': 'Agnes のテキスト→画像（現在無料）',
