  'Agnes 的 size 是档位（1K/2K/3K/4K），不是像素值；参考图放 extra_body。': 'Agnes の `size` は段階（1K/2K/3K/4K）で、ピクセル値ではありません。参照画像は `extra_body` に入れます。',
