  'CPU（慢一点）': 'CPU（やや遅い）',
  'CRF 20 左右画质很好、26~30 是"发出去够用"那一档。原来的宽度没超上限就不放大，只降码率。': 'CRF 20 前後なら画質はとても良く、26〜30 が「送るのに十分」な段階です。元の幅が上限を超えていなければ拡大はせず、ビットレートだけを下げます。',
