  'DSH 沙箱模式：danger-full-access —— 这是「Agent 能用哪些工具」的开关，与上面这些手机权限是两码事（Android 内核没有 landlock，这一项在手机上下调不了）。': 'DSH サンドボックスモード：danger-full-access —— これは「エージェントが使えるツール」のスイッチで、上のスマホ権限とは別物です（Android カーネルには landlock が無いため、スマホでは下げられません）。',
  'DeepSeek API Key（sk- 开头）': 'DeepSeek APIキー（sk- で始まる）',
  'DeepSeek 官方': 'DeepSeek 公式',
  'DeepSeek 官方直连，用的是官方账号自己的额度与计费。适合已经有 DeepSeek 账号、想直接走官方端点的人。': 'DeepSeek 公式への直接接続で、公式アカウント自身の枠と課金を使います。すでに DeepSeek アカウントを持っていて、公式エンドポイントを直接使いたい人向け。',
  'GPU 还没探测（引擎目录未就绪）：先启动一次本地模型，再点右上角刷新，GPU 就会可选。': 'GPU はまだ検出していません（エンジンディレクトリ未準備）。ローカルモデルを一度起動してから右上の更新を押すと、GPU を選べます。',
