  'HTTP 协议层出错：连接被中途关闭，或响应不完整。检查网络后重试。': 'HTTP プロトコル層のエラー：接続が途中で閉じられたか、応答が不完全です。ネットワークを確認して再試行してください。',
  'Key 不对或过期了 —— 回「设置 → 模型」重新填一把再点「测试并保存」。': 'Key が違うか期限切れです — 「設定 → モデル」に戻って入れ直し、「テストして保存」を押してください。',
  'Key 不能为空': 'Key を空にはできません',
  'Key 从哪来：用邮箱在 anysearch.com 注册就能拿一把（免费）。Key 只存在系统安全区，不进配置文件、不进日志。': 'Key の入手先：anysearch.com でメール登録すると無料で 1 本もらえます。Key は OS の安全領域にのみ保存され、設定ファイルにもログにも残りません。',
  'Key 存在「{0}」这家厂家名下（与「云端大模型」里那份是**同一个地方**，填一次两边都认）。留空就不动它 —— 所以这里**从不回显已存的 Key**。': 'Key は「{0}」というベンダー名義で保存されます（「クラウド大規模モデル」のものと**同じ場所**なので、一度入れれば両方で有効）。空欄なら変更しません —— この欄は**保存済みの Key を表示しません**。',
  'Key 已保存到「{0}」这家。': 'Key を「{0}」に保存しました。',
  'Key 无效（401）': 'Key が無効（401）',
  'LongCat（美团）': 'LongCat（美団）',
  'MiMo 的官方接口没有数值语速参数，所以这三档是拼进风格指令里的（「语速放慢一些」这类），效果由模型理解。': 'MiMo の公式 API には数値の速度パラメータがないため、この 3 段階はスタイル指示（「ややゆっくり」など）に文章として織り込み、モデルが解釈します。',
  'MiMo 的音色更自然，但**需要**你在「设置 → 云端大模型 → MiMo」里先填一个 API Key（`tp-` 开头的套餐 Key 会自动走套餐端点）。它出的是 wav（官方文档的格式），语速只能靠指令描述、所以只给三档。': 'MiMo はより自然ですが、**「設定 → クラウドモデル → MiMo」で API Key の入力が必要**です（`tp-` で始まる Key は自動的にトークンプラン端点を使います）。出力は wav（公式ドキュメントの形式）で、速度は言葉で指示するしかないため 3 段階のみです。',
  'MiMo（小米）': 'MiMo（Xiaomi）',
  'MiMo（更自然·需 Key）': 'MiMo（より自然・Key が必要）',
  'MiniMax 出 mp3、语速是真正的倍率，音色可以**从你的账号里拉取**（官方接口现拉，不是我们编的清单）。**需要**你在「设置 → 云端大模型 → MiniMax」里先填 API Key。': 'MiniMax は mp3 を出力し、速度は実際の倍率、音色は**あなたのアカウントから取得**できます（公式 API から都度取得。当方がでっち上げた一覧ではありません）。**「設定 → クラウドモデル → MiniMax」での API Key 入力が必要**です。',
  'MiniMax 吃 aspect_ratio，不吃 size，也不吃参考图。': 'MiniMax は `aspect_ratio` を受け取り、`size` も参照画像も受け付けません。',
