  'MiniMax 的分辨率：H3 只支持 768P / 2K，H3-Max 只支持 480P / 768P（两边都能用的是 768P）；时长 H3 是 4–15 秒、H3-Max 是 5–15 秒（它不支持 4 秒）。': 'MiniMax の解像度：H3 は 768P / 2K のみ、H3-Max は 480P / 768P のみ（両方で使えるのは 768P）。長さは H3 が 4–15 秒、H3-Max が 5–15 秒（4 秒は非対応）。',
