  'OpenAI 的 size 用像素值（1024x1024 这类），比例由尺寸表达；带参考图走 /images/edits multipart。': 'OpenAI の `size` はピクセル値（1024x1024 など）で、比率はサイズで表します。参照画像がある場合は /images/edits の multipart を使います。',
  'OpenCode API Key（同一个 Key 也用于免费那档）': 'OpenCode API Key（同じ Key が無料枠でも使えます）',
  'OpenCode Zen（免 Key）': 'OpenCode Zen（Key 不要）',
