  'Seedream 的 size 用像素值，比例由尺寸表达；参考图放顶层 image 数组。': 'Seedream の `size` はピクセル値で、比率はサイズで表します。参照画像は最上位の `image` 配列に入れます。',
  'TLS/HTTPS 握手失败：可能是网络中间人证书或系统时间不对。': 'TLS/HTTPS ハンドシェイクに失敗：中間者証明書か、システム時刻のずれが考えられます。',
  'Tailscale IP 或局域网 IP': 'Tailscale IP または LAN IP',
  'WebView 不支持它的容器或编码（比如部分 .mkv / .avi）。文件本身没问题 —— 用系统里能放它的应用打开即可。': 'WebView がこのコンテナ／コーデックに対応していません（一部の .mkv / .avi など）。ファイル自体は問題ありません —— 再生できるアプリで開いてください。',
  'as_sk_…（留空 = 按匿名用）': 'as_sk_…（空欄なら匿名のまま）',
  'provider id（写进 overlay 的 providers.<id>）': 'provider id（overlay の providers.<id> に書き込まれます）',
  'size 要用 1024x1024 这类像素值，不是 1K/2K': 'size は 1K/2K のような段階ではなく 1024x1024 のようなピクセル値です',
  'v{0} 你选了跳过。出下一版时会再提示你。': 'v{0} はスキップを選びました。次の版が出たらまたお知らせします。',
  'workspace: {0}\ncreated: {1}\ncreatedBy: 泡泡猫的DSH (Android)\n': 'workspace: {0}\ncreated: {1}\ncreatedBy: 泡泡猫的DSH (Android)\n',
  'wss 必须提供证书指纹——没有指纹就不该信任自签证书': 'wss では証明書フィンガープリントが必須です——フィンガープリントがなければ自己署名証明書を信頼すべきではありません',
