  '{0} 注册 / 申请 Key': '{0} で登録／Key を取得',
  '{0} 类型（{1}）\n交给系统里能打开它的应用试试：': '{0} タイプ（{1}）\nシステム上で開けるアプリに任せてみてください：',
  '{0} 起不来，已自动改用 {1}（优先保证能用）': '{0} が起動しないため、{1} に自動で切り替えました（使えることを優先）',
  '{0}: 无法列出目录（{1}）': '{0}: ディレクトリを一覧できません（{1}）',
  '{0}: 无法判断目录是否存在（{1}）': '{0}: ディレクトリの存在を確認できません（{1}）',
  '{0}: 无法读取文件信息（{1}）': '{0}: ファイル情報を読み取れません（{1}）',
