  '{0}（本机服务没在运行）': '{0}（オンデバイスサービスが起動していません）',
  '{0}（正在回答）': '{0}（回答中）',
  '{0}，{1} 个模型，{2}，{3}': '{0}、{1} モデル、{2}、{3}',
  '{0}，{1}，{2} 个模型，{3}': '{0}、{1}、{2} モデル、{3}',
  '{0}：这个入口还没接入': '{0}：この入り口はまだ接続されていません',
  '…还有 {0} 条，去发布页能看到全部。': '…ほか {0} 件。すべてはリリースページで見られます。',
  '⚠️ 三点如实说明：\n· 搜索请求会发到 **api.anysearch.com**（这是联网功能，不是本机算的）。\n· 它**在建会话那一刻**挂上去 —— 改完之后要**开一个新会话**才生效，老会话不变。\n· 匿名层限流较低：搜得太频繁会被限，等一会儿或填一把 Key。': '⚠️ 正直に三点：\n· 検索リクエストは **api.anysearch.com** に送られます（端末内で計算する機能ではありません）。\n· 装着されるのは**セッション生成時**です —— 変更は**新しいセッション**から有効で、既存セッションは変わりません。\n· 匿名レイヤーはレート制限が低めです。頻繁に検索すると制限されるので、少し待つか Key を入れてください。',
  '⚠️ 两点如实说明：\n· 多一层子 agent = **多一份 token 与时间**（子会话也要跑模型），用免费那条小模型通道时尤其明显。\n· 改完**只在下一个会话生效**（会话进程启动时才读这份配置）。': '⚠️ 正直に二点：\n· 子エージェントを一段挟むと **トークンと時間が余分にかかります**（子セッションもモデルを回すため）。無料の小さいモデル経路では特に目立ちます。\n· 変更は**次のセッション**から有効です（設定はセッション起動時に読まれます）。',
  '⚠️ 先说清它能做什么、不能做什么：\n· 匿名层**只有一个 20B 级的模型**（`openai-fast`）：聊天、用工具都行，但**不是聪明模型** —— 写小说、长文、画布这类重活它接不住，那些请用自己的模型。\n· 有速率限制（人多了会慢或被限），失败了再试一次即可。\n· 上游是社区项目，**随时可能变**；真变了他会如实报错，不会假装成功。\n· 用不到时把开关关掉即可，你自己的模型配置一点都不会动。': '⚠️ できること・できないことを先に：\n· 匿名レイヤーのモデルは**20B クラスが 1 つだけ**（`openai-fast`）。チャットとツール利用は可能ですが、**賢いモデルではありません** —— 小説・長文・キャンバス系の重い作業には向きません。それらはご自身のモデルで。\n· レート制限があります（混雑時は遅くなる／拒否される）。その場合は再試行してください。\n· 上流はコミュニティプロジェクトで、**いつ変わるか分かりません**。変わったときは正直にエラーを出し、成功したふりはしません。\n· 不要なときはスイッチをオフに。ご自身のモデル設定には一切触れません。',
  '⚠️ 只提示、不替你判断：去掉**别人版权作品**上的水印有侵权风险（尤其发布或商用时）。': '⚠️ 注意喚起のみで、判断はお任せします：**他人の著作物**の透かしを消すのは権利侵害の恐れがあります（公開・商用時は特に）。',
  '⚠️ 本页不显示这 5 项的实时状态：Android 只在系统页面里读 / 改它们（要在这里显示，得再加一个原生查询接口，这一版没做）。是否已开启，以系统页面里的开关为准。': '⚠️ このページは 5 項目の現在の状態を表示しません：Android はこれらをシステムページ内でのみ読み書きします（ここに表示するにはネイティブの照会 API を追加する必要があり、この版では未実装です）。実際の状態はシステムページのスイッチで確認してください。',
  '⚠️ 请先看清楚：\n· 上游的免费额度**只给它自家客户端用**，这条通道是把请求**伪装成官方 CLI** 去通过它的限制 —— 属于灰色用法，**随时可能失效**（自 2026-09-16 起已收紧 6 次：换过端点、加过会话头、工具指纹从两个涨到四个）。\n· **它不需要任何 Key**：那条通道本来就是匿名的（上游凭据就是公开的 `public`），所以你不用在这里填任何东西；失效时它会如实报错，不会假装成功。\n· 它按出口 IP 限流，被限流时等一会儿再试。\n· 本 App **不做** IP 轮换、也不做反复重试（不拿它去刷额度）。\n· 用不到时请把它关掉。': '⚠️ 先にお読みください：\n· 上流の無料枠は**自社クライアント専用**で、このチャネルはリクエストを**公式 CLI に見せかけて**通します — グレーな使い方で、**いつ止まってもおかしくありません**（2026-09-16 以降に 6 回のゲート変更：エンドポイント移転、セッションヘッダ追加、ツール指紋が 2 個から 4 個へ）。\n· **Key は不要**：このレーンはもともと匿名です（上流の資格情報は公開語 `public`）。ここに入力するものは何もありません。失敗時は正直にエラーを出し、成功を装いません。\n· 出口 IP ごとのレート制限があります。制限されたら少し待ってください。\n· 本アプリは IP ローテーションも**しません**し、繰り返し再試行も**しません**（枠を掘りません）。\n· 不要なときはオフにしてください。',
  '⚠️ 请求形状按各家的文档写（端点、参数名、轮询都不一样）—— **能不能通要试**；失败会把上游原话显示出来。': '⚠️ リクエスト形式は各社のドキュメントどおりです（エンドポイント・パラメータ名・ポーリングがそれぞれ異なります）—— **通るかどうかは試すしかありません**。失敗時は上流の文言をそのまま表示します。',
  '⚠️ 边界（别踩）：图像与视频都**按厂家的形状**发 —— 端点、参数名、轮询各不相同（唯一来源是 assets/toolbox/media-vendors.mjs）。本机没有这些厂家的 Key、也没法真机验证，所以**能不能通要试**；失败了会把上游原话显示出来，不假装成功。': '⚠️ 限界：画像も動画も**各社の形式**で送ります —— エンドポイント・パラメータ名・ポーリングはそれぞれ異なります（唯一の出所は assets/toolbox/media-vendors.mjs）。本機にはこれらのベンダーの Key がなく、実機検証もできないため、**通るかどうかは試すしかありません**。失敗時は上流の文言をそのまま表示し、成功したふりはしません。',
  '⚠️ 这个模型的对话模板可能与 DSH 不兼容（启动自检没通过）：发消息很可能直接失败。请到「设置 → 运行日志」导出后发回，我会按真实报错改。': '⚠️ このモデルの会話テンプレートは DSH と互換性がない可能性があります（起動セルフチェック失敗）。メッセージ送信は失敗する見込みです。「設定 → 実行ログ」を書き出して送ってください。実際のエラーに基づいて修正します。',
  '✗ 名字不合法。{0}': '✗ 名前が不正です。{0}',
  '　「自定义」是占位：还没做，点了会如实说明，不会把主题切到一个不存在的状态。': '　「カスタム」はプレースホルダーです：未実装で、タップすると正直にそう表示し、存在しない状態にテーマを切り替えることはありません。',
  '　当前语言：{0}（{1}）': '　現在の言語：{0}（{1}）',
  '「{0}」已经在池子「{1}」里了。': '「{0}」はすでにプール「{1}」にあります。',
  '「{0}」已经登记，但名下一条模型都没有 —— 现在选中它没有任何模型可用。\n去「设置 → 模型 → 我的模型」点开这家：{1}点「测试并保存」（它会自动把模型登记进来），或点「获取模型」自己勾几个。': '「{0}」は登録済みですがモデルが1つもありません — 今選んでも使えるモデルがありません。\n「設定 → モデル → マイモデル」でこのサービスを開いてください：{1}「テストして保存」を押すと（モデルを自動で登録します）、または「モデルを取得」で自分でいくつか選べます。',
  '「{0}」执行失败：{1}': '「{0}」の実行に失敗：{1}',
  '「{0}」执行异常：{1}': '「{0}」の実行で例外：{1}',
  '「{0}」执行成功：{1}': '「{0}」の実行に成功：{1}',
  '「{0}」的 Key 去哪拿': '「{0}」のキーはどこで取得するか',
  '「{0}」还没配 API Key —— 现在选中它，发言时必然失败。去「设置 → 模型 → 我的模型」填 Key 并「测试并保存」。': '「{0}」は API Key が未設定です — 今選ぶと発言時に必ず失敗します。「設定 → モデル → マイモデル」で Key を入力し「テストして保存」を押してください。',
  '「作品」里还没有图片 —— 先生成一张，或用上面的按钮选一张。': '「作品」にまだ画像がありません。まず生成するか、上のボタンで選んでください。',
  '「免费模型（无需 Key）」这条通道被上游关掉了（不是你没配 Key —— 它本来就不用 Key）。\n下一步：去「设置 → 模型」换一个自己配了 Key 的模型；这条通道以后再恢复就能继续用。': '「無料モデル（Key 不要）」の経路は上流側で閉じられました（Key を設定していないからではありません —— この経路はもともと Key が不要です）。\n次の一手：「設定 → モデル」で、ご自身で Key を設定したモデルに切り替えてください。この経路が復活すればまた使えます。',
  '「推理后端」和「上下文长度」会记住：下次进这一页、下次启动本地服务都以它为准。': '「推論バックエンド」と「コンテキスト長」は記憶されます。次にこのページを開くとき、次にローカルサービスを起動するときに反映されます。',
  '一': '一',
  '一个 Key 即可用 DeepSeek / MiMo / LongCat / GLM / Qwen / Claude / GPT 等全部模型。': 'Key ひとつで DeepSeek / MiMo / LongCat / GLM / Qwen / Claude / GPT など全モデルが使えます。',
  '一句话就能得到真实文件：PPT、文档、表格、图、视频。': 'ひとこと伝えるだけで実ファイルが手に入ります：スライド・文書・表計算・画像・動画。',
  '一句话或一张参考图，生成图片': 'ひとこと、または参考画像から画像を生成',
  '一屏能看更多内容': '1 画面でより多く表示',
  '一条都没加进去。': '1 件も追加されませんでした。',
  '一行一个镜头。例如：\n深夜的办公室只剩一盏灯\n他盯着屏幕上的数字，笑了一下\n门开了，站着他的老板': '1行＝1ショット。例：\n深夜のオフィスに灯りが一つ\n彼は画面の数字を見つめて笑った\nドアが開き、上司が立っていた',
  '一键发给开发者': '開発者に送る',
  '一键美化': 'ワンタップ補正',
  '万相只有文生视频（不吃首帧图），分辨率 720P / 1080P。': '万相はテキストからの動画生成のみ（先頭フレームは受け付けません）で、解像度は 720P / 1080P です。',
  '万相没有比例参数：比例由尺寸表达（1280x720 就是 16:9），而且走异步任务。': '万相には比率パラメータがありません：比率はサイズで表します（1280x720 は 16:9）。また非同期タスクで実行されます。',
  '万相走异步任务（不是 OpenAI 兼容入口），尺寸用 1024*1024 这种写法': '万相は非同期タスクです（OpenAI 互換エントリではありません）。サイズは 1024*1024 の形で指定します',
  '三': '三',
  '三个更新源都没连上（多半是网络问题，过一会儿再试）。': '3 つの更新元のどれにも接続できませんでした（多くはネットワークの問題です。しばらくしてからお試しください）。',
  '三步打开后台操作': '3 ステップでバックグラウンド操作',
  '三色档位怎么算的': '3 段階の判定方法',
  '上下文估算：约 {0}（{1} 条消息 · 约 {2} tokens）{3}': 'コンテキスト推定：約 {0}（{1} 件のメッセージ・約 {2} tokens）{3}',
  '上下文超出该模型上限。请精简输入，或换一个上下文窗口更大的模型。': 'コンテキストがこのモデルの上限を超えています。入力を減らすか、コンテキストウィンドウがもっと大きいモデルに切り替えてください。',
  '上下文长度': 'コンテキスト長',
  '上下文长度（可选）': 'コンテキスト長（任意）',
  '上次同步：{0}': '最終同期：{0}',
  '上次检查': '前回の確認',
  '上游把请求当成"非官方客户端"拒了。这条通道可能已经变了，把自检结果发给开发者核对。': '上流が「非公式クライアント」とみなして拒否しました。このチャネルは変わった可能性があります。自己診断の結果を開発者に送って確認してください。',
  '上游自己出问题了，过一会儿再试（不是你的配置问题）。': '上流側の不具合です。少し待って再試行してください（あなたの設定の問題ではありません）。',
  '上游自身故障（5xx）': '上流側の障害（5xx）',
  '上游那套自带的示例游戏（含成人向题材）**没有随包**；题材与分级请自己把握。': '上流が同梱しているサンプルゲーム（成人向け題材を含む）は**同梱していません**。題材とレーティングはご自身でご判断ください。',
  '上移': '上へ',
  '上移（会更早被尝试）': '上へ（より早く試されます）',
  '下次：{0}': '次回：{0}',
  '下移': '下へ',
  '下移（会更晚被尝试）': '下へ（より遅く試されます）',
  '下载': 'ダウンロード',
  '下载不完整：只拿到 {0}，应为 {1}。': 'ダウンロードが不完全です。{1} のうち {0} しか取得できませんでした。',
  '下载中 {0} / {1} · {2}/s': 'ダウンロード中 {0} / {1} · {2}/s',
  '下载中 {0}%': 'ダウンロード中 {0}%',
  '下载中断（拿到 {0} / {1} 字节）—— 已保留进度，可以重试续传。': 'ダウンロードが中断しました（{0} / {1} バイト）—— 進捗は保持しているので再開できます。',
  '下载中断：传输出错。': 'ダウンロードが中断しました：転送エラー。',
  '下载中断：连接断了。': 'ダウンロードが中断しました：接続が切れました。',
  '下载中断：连接被提前关掉了（{0}）。已保留进度，可以重试续传。': 'ダウンロード中断：接続が途中で閉じられました（{0}）。進捗は保持しているので再開できます。',
  '下载出错了：{0}': 'ダウンロードに失敗しました：{0}',
