  '下载到的包校验没通过（哈希不符），已删除。这通常是下载中途坏了，请重试一次。': 'ダウンロードしたパッケージの検証に失敗しました（ハッシュ不一致）。削除しました。多くはダウンロード途中で壊れたためです。もう一度お試しください。',
  '下载在**本机**做，断了能接着下；装之前会**验两样** —— 文件哈希（没下坏）+ 签名（跟现在这个 App 是同一把钥匙签的）。签名对不上就不给你装，这是防止包被替换的那道闸。': 'ダウンロードは**この端末内**で行い、途中で切れても続きから再開できます。インストール前に**2 つ確認**します —— ファイルのハッシュ（壊れていないか）と署名（このアプリと同じ鍵で署名されているか）。署名が一致しなければインストールしません。これがパッケージのすり替えを防ぐ関門です。',
