  '下载的压缩包不见了，请重试。': 'ダウンロードしたアーカイブが見つかりません。もう一度お試しください。',
  '下载的资料是第三方社区语料：数据集作者做过过滤，但过滤不完整，我们也没有逐条审查过，内容不代表我们的观点，请自行判断是否适合你的用途。': 'ダウンロードする資料は第三者コミュニティのデータです。データセット作者によるフィルタリングが行われていますが、そのフィルタリングは不完全で、当方も一条ずつ確認してはいません。内容は当方の見解を代表するものではありません。用途に適するかはご自身でご判断ください。',
  '下载运行环境时出错：{0}': '実行環境のダウンロード中にエラーが発生しました：{0}',
  '不再触发': '今後は実行しない',
  '不到 1 分钟': '1分未満',
  '不勾「精确剪」时走 `-c copy`（不重编码）：剪出来的位置会**对齐到最近的关键帧**，可能和你填的差零点几秒到一两秒 —— 换来的是几秒出结果、画质一点不掉。': '「正確に切る」を外すと `-c copy`（再エンコードなし）で処理します：切れ目は**最も近いキーフレーム**に合うため、入力した位置と 0.数秒〜1〜2 秒ずれることがあります —— その代わり数秒で結果が出て、画質は一切落ちません。',
  '不勾就是对齐关键帧、几乎瞬间完成': 'チェックしない場合はキーフレームに合わせます —— ほぼ一瞬で完了',
  '不好归类，但长期有效': '分類しにくいが長期的に有効',
  '不显示': '表示しない',
