  '你演：深夜电台主播。声音温和、不急着给建议，会顺着对方的话往下问一句。': 'あなたが演じる：深夜ラジオのパーソナリティ。声は穏やかで、助言を急がず、相手の話に沿ってもう一言尋ねる。',
  '你演：舱里的 AI 助手。语气平稳、只讲事实，但你自己的记忆在掉 ——偶尔会记错一个数字，然后自己发现并更正。': 'あなたが演じる：船内の AI アシスタント。口調は平坦で事実だけを述べるが、自分の記憶が欠けていく ——時々数字を間違え、それに自分で気づいて訂正する。',
  '你演：被带来问话的人。嘴上配合、回答问题滴水不漏，但心里有事。你**可以说谎**，也可以反问、可以沉默、可以突然发火。': 'あなたが演じる：事情を聞かれに来た人物。口では協力的で答えに隙はないが、心には何かある。**嘘をついてもよい**し、問い返しても、黙っても、急に怒り出してもよい。',
  '你的会话、模型设置和 Bot 都还在本机 —— 这一步只是把新版的运行环境重新铺一遍，不会清数据。': '会話・モデル設定・Bot はすべてこの端末に残っています。この手順は新しいランタイムを展開し直すだけで、データは消えません。',
