  '做这个主要是下班晚上才有时间做，而且本人公众号一直没有人关注，要求不多：），麻烦大家点个关注就行': 'これは主に仕事終わりの夜にしか作れなくて、個人のアカウントは全然フォロワーがいません。多くは望みません：）、よかったらフォローをお願いします。',
