  '允许 App 在别的应用上面显示小窗 —— 语音输入与「取图后回到本页」的提示会用到。不给也能用，只是这类提示可能被系统挡住。': '他のアプリの上に小さなウィンドウを表示できるようにします —— 音声入力と「画像を選んだ後にこのページへ戻る」案内で使います。オフでも動きますが、そうした案内がシステムに隠されることがあります。',
