  '先写一句大概的想法，我再帮你写专业。': 'まず大まかなアイデアを書いてください。あとは専門的に整えます。',
  '先写点内容再添加': '先に内容を書いてください',
  '先填 Base URL 再拉模型列表。': '先に Base URL を入力してから、モデル一覧を取得してください。',
  '先建一块虚拟屏，这里就会出现画面': '先に仮想ディスプレイを作成すると、ここに画面が表示されます',
  '先把虚拟屏建起来，再点「载入应用列表」选一个 App 拉进去。': 'まず仮想ディスプレイを作成し、「アプリ一覧を読み込む」からアプリを選んで送り込んでください。',
  '先看引擎有没有（没有 → 红）；引擎有再看内存（不够 → 红；余量不足 2 GB、或 2 GB 以上文件装在 8 GB 机上 → 白）；都过 → 绿。点【测试】真跑一次之后，改用实测速度判：低于 5 tok/s 红、5–10 白、10 以上绿。': 'まずエンジンの有無（無ければ赤）、次にメモリ（不足なら赤、余裕 2 GB 未満または 8 GB 端末で 2 GB 以上のファイルなら白）、両方通れば緑。［テスト］で実際に走らせた後は実測速度で判定します：5 tok/s 未満は赤、5〜10 は白、10 以上は緑。',
  '先确认手机能上网（换 WiFi/流量试一下）；如果用代理，看代理是否在跑。': 'まずスマホがネットにつながるか確認（Wi-Fi／モバイル通信を切り替えてみる）。プロキシを使っているなら、動いているか確認してください。',
  '先粘贴 Key 再保存（留空不会改动已存的 Key）。': '保存する前に Key を貼り付けてください（空欄なら保存済みの Key は変更されません）。',
  '先选一张图（要按原图尺寸算框的位置，读不出尺寸就不给用）': 'まず写真を選んでください（枠の位置は元画像のサイズから計算します。読めないときは使いません）',
  '先选一张要修的图。': 'まず編集する写真を選んでください。',
  '免装 Shizuku 的 adb 通道（2026-10-24 新增，随包）\n\n· libadb-android 3.1.1 —— adb 协议与「无线调试配对」的实现。双许可（GPL-3.0 或 Apache-2.0），本 App 按 Apache-2.0 使用。https://github.com/MuntashirAkon/libadb-android\n\n· Conscrypt 2.5.3 —— TLS 实现（无线调试配对用）。Apache-2.0。https://github.com/google/conscrypt\n\n· Bouncy Castle 1.78.1（bcprov / bcpkix）—— adb 认证证书的生成。MIT 许可。https://www.bouncycastle.org\n\n以上组件只用于本 App 自带的「无线调试配对」功能（让用户不装 Shizuku 也能启动后台引擎），源码均未修改。': 'Shizuku 不要モードの adb チャンネル（2026-10-24 追加、同梱）\n\n· libadb-android 3.1.1 — adb プロトコルとワイヤレスデバッグのペアリング。デュアルライセンス（GPL-3.0 または Apache-2.0）、本 App は Apache-2.0 で使用。https://github.com/MuntashirAkon/libadb-android\n\n· Conscrypt 2.5.3 — ペアリング用 TLS。Apache-2.0。https://github.com/google/conscrypt\n\n· Bouncy Castle 1.78.1（bcprov / bcpkix）— adb 認証証明書の生成。MIT。https://www.bouncycastle.org\n\nこれらは本 App 内蔵のワイヤレスデバッグペアリング（Shizuku を入れずにバックグラウンドエンジンを起動するため）にのみ使用し、ソースは改変していません。',
  '免装 Shizuku（用无线调试自己起引擎）': 'Shizuku 不要（ワイヤレスデバッグでエンジンを起動）',
