  '凌晨两点的直播间，一通"我没事，就是想说说话"的电话': '深夜2時の放送ブース、一本の電話は「大丈夫です、ただ話がしたくて」',
  '凌晨两点，一盏台灯。他是被带来问话的人 —— 而他在装': '深夜2時、机のライトが一つ。彼は事情を聞かれに来た人物 —— そして演じている',
  '凌晨两点，直播间只剩你一个人。刚接进来一通电话，对方第一句是「我没事，就是想说说话」。': '深夜2時、放送ブースにはあなた一人。ちょうど電話が一本入り、相手の第一声は「大丈夫です、ただ話がしたくて」。',
  '凌晨的审讯室，一盏台灯照着桌面，屋外没有声音。问你的是一位进来就没坐下的警官。': '明け方前の取調室、机を照らすライトが一つ、外からは物音ひとつしない。尋ねる警官は入ってきてから一度も座らない。',
  '几个模型排成一队：前一个不可用就自动换下一个': '複数のモデルを順番に並べて、前のが使えなければ自動で次に切り替わります',
  '几段不是同一种格式时勾上：先把每段统一成第一段的规格再拼': '各クリップの形式が違うときにオン：まず全部を 1 本目と同じ仕様に揃えてからつなぎます',
