  '分类和重要度可以直接改。加入后是「全局」记忆（每个工作目录都注入）；想限定某个目录，可以在条目上再改。': '分類と重要度はここで直接変えられます。追加後は**全体**の記憶になります（どの作業ディレクトリにも注入）。特定のフォルダに限りたい場合は、あとで項目側で変更してください。',
