  '切换会重启本地服务（几秒到几十秒）。对话记录不清空 —— 新模型能看到之前的对话。': '切替はローカルサービスを再起動します（数秒〜数十秒）。会話履歴は消えません —— 新しいモデルも以前の会話を見られます。',
  '切换到 {0}': '{0} に切り替え',
