  '切换失败：引擎没起来（详见运行日志）': '切替失敗：エンジンが起動しませんでした（実行ログ参照）',
  '切换本地模型': 'ローカルモデルを切替',
  '切界面文案，点一下立即生效、重启后保持': 'UI の文言を切り替え。タップで即反映、再起動後も維持されます',
  '切的是 App 自己画的界面：导航、设置、按钮、内置提示。电脑上那台 DSH 回传的内容 —— 会话消息、技能名、专家库、后端报错 —— 是它给的，保持原文，App 不替它决定用什么语言。': '切り替わるのはアプリ自身が描く画面だけです：ナビ、設定、ボタン、内蔵のヒント。DSH が返す内容（会話メッセージ、スキル名、専門家ライブラリ、バックエンドのエラー）はそのまま原文で表示され、言語はアプリが決めません。',
