  '厂家名': 'プロバイダ名',
  '厂家和 Key 都有了，但还没有模型：去「设置 → 模型」点「获取模型」，勾好模型再保存，会话里才会出现可选模型。（想省事也可以先打开「免费模型（无需 Key）」。）': 'プロバイダーと Key はあるのにモデルがありません：「設定 → モデル」で「モデルを取得」を押し、使うモデルにチェックして保存すると、セッションで選べるようになります。（手っ取り早くなら「無料モデル（Key 不要）」をオンにしても構いません。）',
  '历史会话': '履歴セッション',
  '历史会话 · {0} · {1} · DSH 未提供标题': '過去のセッション · {0} · {1} · DSH からタイトル未提供',
  '历史会话读取失败：运行时没起来或未配置模型（不影响下方本次会话）': '過去のセッションを読み込めませんでした：ランタイムが起動していないか、モデルが未設定です（下の今回のセッションには影響しません）',
  '压小': '小さくする',
  '压小要重新编码，按片长等：手机上处理 1 分钟 1080p 大约要几十秒到几分钟。': '小さくするのは再エンコードなので尺なりに時間がかかります：1080p の 1 分で、スマホでは数十秒〜数分ほど。',
  '压缩包大小不对（{0} 字节，应为 {1}）——下载不完整，已删掉，请重试。': 'アーカイブのサイズが違います（{0} バイト・本来は {1}）—— ダウンロードが不完全です。削除しましたので、もう一度お試しください。',
  '压缩包校验不通过（sha256 对不上）——已删掉，请重试。如果总是这样，可能是网络中间有东西改了内容。': 'チェックサムが一致しません（sha256）—— アーカイブを削除しました。もう一度お試しください。繰り返す場合、経路上で内容が改変されている可能性があります。',
  '原因未知': '原因不明',
  '原因：{0}\n画面和字幕都在；每一镜的时长是按文字长度**估**的。想要声音就改用 MiMo 或 MiniMax（各填一个 Key）再生成一次。': '理由：{0}\n映像と字幕はそのまま入っています。各ショットの長さは文字数からの**推定**です。音声が欲しい場合は MiMo か MiniMax に切り替えて（それぞれ Key を入力）もう一度生成してください。',
  '原图': '元画像',
