  '去「专家」页打开开关，开启的专家会出现在这里。': '「エキスパート」ページでスイッチをオンにすると、有効にしたエキスパートがここに表示されます。',
  '去「设置 → 模型 → 我的模型」：点开一家内置厂家（地址已经内置好）→ 只填 API Key → 点「测试并保存」。\n\n保存成功后，这里就会按厂家分组列出你的模型，点一下就能用；此前那种"没配置也能随便切模型"的假象，就是硬编码清单造成的。': '「設定 → モデル → マイモデル」へ：内蔵メーカーを開き（エンドポイントは入力済み）→ API Key を貼るだけ → 「テストして保存」を押します。\n\n保存できれば、ここにメーカー別でモデルが並び、タップするだけで切り替わります。以前「未設定でも自由に切り替えられる」ように見えたのは、ハードコードされた一覧のせいでした。',
