  '参与检索': '検索に使う',
  '参数': '設定',
  '参数不一致时重新编码（慢）': '形式が違うときは再エンコード（遅い）',
  '参数或模型不被支持：请确认模型名可用，并确认该模型支持 OpenAI 兼容协议。': 'パラメータまたはモデルが未対応です：モデル名が有効か、そのモデルが OpenAI 互換プロトコルに対応しているかを確認してください。',
  '参考图最多 4 张。': '参照画像は最大4枚です。',
  '参考图（可选，最多 4 张）': '参照画像（任意・最大4枚）',
  '双语对照，不是机翻腔': '対訳形式。機械翻訳くさくしない',
  '发消息…': 'メッセージ…',
  '发消息前记得先把模型选好哦。': 'メッセージを送る前にモデルを選んでね。',
  '发现新版本 v{0}': '新しいバージョン v{0} があります',
  '发送': '送信',
  '发送失败：{0}': '送信に失敗しました：{0}',
  '取到了 {0} 个免费模型，已写进列表。': '{0} 個の無料モデルを取得し、一覧に追加しました。',
  '取消': 'キャンセル',
  '取消下载': 'ダウンロードを中止',
  '取消提炼': '抽出を中止',
  '取消生成': '生成を中止',
  '变暗': '暗さ',
  '口播': 'ナレーション',
  '口播与短剧': 'ナレーションとショートドラマ',
  '另外接口返回的 {0} 个是图像/视频模型 —— 那些端口是内置的（生成图片/视频时自动调用），不列进会话的模型列表。': 'なお、返ってきたうち {0} 件は画像/動画モデルです —— そのエンドポイントは組み込みで（画像/動画の生成時に自動で呼ばれます）、セッションのモデル一覧には表示されません。',
  '只会删掉这个池子（{0} 个成员）和它在模型面板里的那一项；成员模型本身与各厂家的 Key 都不动。': '削除されるのはこのプール（メンバー {0} 個）とモデルパネル内の該当項目だけです。メンバーのモデル本体と各プロバイダの Key はそのままです。',
  '只信任这个指纹的证书，其它一律拒绝': 'この指紋の証明書だけを信頼し、それ以外はすべて拒否します',
  '只列了最近 {0} 个（共 {1} 个，按修改时间倒序；要看全部请用搜索或「我的资料」）': '最新の {0} 件のみ表示（全 {1} 件、更新日時の新しい順。すべて見るには検索か「マイ資料」を使ってください）',
  '只列出最近的 10 条磁盘会话（没有消息的空会话不列）。': 'ディスク上の直近 10 セッションのみ表示します（メッセージのない空のセッションは除外）。',
  '只列本 App 真正会用到的那几项。点「申请」才会弹系统授权框 —— Android 不允许应用给自己开权限，也没有「一键全开」这种接口。': 'このアプリが実際に使う項目だけを載せています。「申請」を押して初めてシステムの許可ダイアログが出ます —— Android はアプリ自身が自分に権限を与えることを許さず、「一括許可」API もありません。',
  '只发最小的探测请求（免 Key 那条会真发一句话，1 个字）：不写任何文件、不读你的资料、不把结果上传给任何人。': '最小限のプローブだけを送ります（Key 不要のチャネルは実際に 1 トークンの一言を送ります）：ファイルは書かず、あなたのデータも読まず、結果も誰にも送りません。',
  '只在这个工作目录下适用：{0}': 'この作業ディレクトリでのみ有効：{0}',
  '只存本机安全区（Android Keystore）：不写进 models.json、不进日志、界面上也读不出来；填完点「测试并保存」。': '端末のセキュア領域（Android Keystore）にのみ保存します：models.json には書かず、ログにも出さず、画面からも読み出せません。入力したら「テストして保存」を押してください。',
  '只存本机安全区：不写进 models.json、不进日志。': '本機のセキュア領域にのみ保存：models.json にもログにも書き込みません。',
  '只把声音拿出来存成 .m4a（声音原样搬，不掉音质）': '音だけを取り出して .m4a に（そのままコピーなので音質は落ちません）',
  '只支持英文/数字/符号': '英字・数字・記号のみ',
  '只是从影视页的候选里去掉，不影响你的 Key。': '「影视」ページの候補から外れるだけで、Key には触りません。',
  '只是试一下：微信已不响应这条指令时，它会显示「页面无法访问」。': '試すだけ：WeChat がこのコマンドに応じない場合、「ページを開けません」と表示されます。',
  '只显示搜索结果前 {0} 条；继续输入缩小范围': '検索結果の先頭 {0} 件のみ表示。入力して絞り込んでください',
  '只有需要一个"更便宜/更小的模型去干粗活"时才需要改它；默认跟随当前会话。': '「安い／小さいモデルに雑用をやらせたい」ときだけ変えてください。既定は現在のセッションに追従します。',
  '只能用字母、数字和横线；它会作为模型名出现在会话的模型面板里。': '使えるのは英数字とハイフンのみ。セッションのモデルパネルにモデル名として表示されます。',
  '只能选图片。': '画像のみ選択できます。',
  '只能选图片（修图要一张图）。': '画像だけ選べます（レタッチには画像が必要です）。',
  '只能选图片（参考图/首帧要图片）。': '画像のみ（参照画像・先頭フレームは画像が必要）。',
  '只需要填 API Key': '入力が必要なのは APIキー だけです',
  '可下载': 'ダウンロード可能',
  '可多选。网盘、微信、数据线拿到的模型文件都从这里进来，不需要存储权限。': '複数選択可。クラウドストレージ・WeChat・ケーブル経由のモデルファイルもここから取り込めます。ストレージ権限は不要です。',
  '可点 / 可拖': 'タップ／ドラッグ可',
  '可用 · 系统识别服务': '利用可 · システム認識サービス',
  '可用 · 设备端离线识别': '利用可 · デバイス上のオフライン認識',
  '可看图': '画像対応',
  '可选模型共 {0} 个 —— 在下面的列表里点一下就会加进这里。': '選択可能なモデルは {0} 個 —— 下のリストでタップするとここに追加されます。',
  '可选的图像模型': '選択できる画像モデル',
  '可选的视频模型': '選択できる動画モデル',
  '右上': '右上',
  '右下': '右下',
  '各厂家的 Key（点一下就能填）': 'ベンダーごとの Key（タップして入力）',
  '各通道都是正常的。': '各チャンネルとも正常です。',
  '合成中…（{0} 镜）': '合成中…（{0} ショット）',
  '同一份模型文件，区别只是"谁来算"：仅 CPU = 手机 CPU 算，慢但几乎所有手机都能跑；Vulkan = 交给手机 GPU 算，通常快 2–5 倍、更省电，需要 Android 9 以上。切换后端要重启服务。同一个模型两个后端各测一次，就能直接比出哪个快。': '同じモデルファイルで、違いは「誰が計算するか」だけです。CPU のみ＝スマホの CPU（遅いがほとんどの端末で動作）、Vulkan＝スマホの GPU（通常 2〜5 倍速く省電力、Android 9 以上が必要）。切り替えにはサービスの再起動が必要です。同じモデルを両方で計測すれば比較できます。',
  '同步到系统日历': 'システムカレンダーに同期',
  '后台操作台': 'バックグラウンド操作台',
  '后台运行依赖一个常驻通知把 App 留在后台。部分手机（尤其是国产 ROM 的省电策略）仍会杀掉进程，建议到系统设置里关闭本 App 的电池优化。App 被彻底杀掉期间不会触发，恢复后会把错过的记录标成「已错过」。': 'バックグラウンド実行は常駐通知でアプリを生かし続けます。一部の端末（特に中国系 ROM の省電力ポリシー）はそれでもプロセスを終了させます。システム設定でこのアプリのバッテリー最適化をオフにすることをおすすめします。アプリが完全に終了している間は発火せず、復帰後に逃した記録は「逃した」と表示されます。',
  '后天 {0}:{1}': '明後日 {0}:{1}',
  '含视觉编码器（mmproj）': '視覚エンコーダ（mmproj）を含む',
  '含运行环境': '実行環境を含む',
  '启动': '起動',
  '启动 node 解包失败：{0}': '展開用の node を起動できません：{0}',
  '启动后自动检查': '起動時に自動で確認',
  '启动失败：{0}': '起動に失敗：{0}',
  '启动次数：{0}': '起動回数：{0}',
  '启用 TLS 时必须填证书指纹（电脑端启动桥时会打印）': 'TLS を有効にするときは証明書の指紋が必須です（コンピュータ側でブリッジ起動時に表示されます）',
  '启用免 Key 免费模型': 'Key 不要の無料モデルを有効にする',
  '启用社区免费通道': 'コミュニティ無料チャンネルを有効化',
  '响应不是 JSON': '応答が JSON ではありません',
  '喵～今天想聊点什么？': 'にゃ〜今日は何を話そうか？',
  '四': '四',
  '回「设置 → 模型」把「免费模型 · OpenCode Zen」打开一次（它会起代理），然后再点自检。': '「設定 → モデル」に戻って「無料モデル · OpenCode Zen」を一度オンにしてください（代理が起動します）。その後で自己診断を実行してください。',
  '回「设置 → 模型」点一次「获取模型」重新拉；一直拉不到就说明上游这条通道又变了，把自检结果发出去核对。': '「設定 → モデル」に戻って「モデルを取得」を一度押してください。何度やっても取れないなら上流のチャネルがまた変わっています。自己診断の結果を送って確認してください。',
  '回创作台': 'スタジオに戻る',
  '回答中': '回答中',
  '回首页': 'ホームに戻る',
  '因为上一轮没回完': '前のターンが完走しなかったため',
  '因为对话历史对不上': '会話履歴が一致しなかったため',
  '因为换了模型或参数': 'モデルまたはパラメータが変わったため',
  '因为系统提示变了': 'システムプロンプトが変わったため',
  '国内集群是「冰糖」': '中国クラスタでは「冰糖」',
  '图像 / 视频模型': '画像 / 動画モデル',
  '图像 / 视频走哪家，就用哪家的 Key；存的位置和「云端大模型」**同一个**，在哪边填都认。': '画像／動画がどのベンダーを通るかでその Key を使います。保存先は「クラウド大規模モデル」と**同じ**なので、どちらで入力しても有効です。',
  '图像模型': '画像モデル',
  '图像用 aspect_ratio，不用 size': '画像は size ではなく aspect_ratio を使います',
  '图像请求的形状**按各家的文档写**（size 是像素值还是 1K/2K 档位、参考图放哪、要不要 response_format 都不同）—— 本机没有这些厂家的 Key，**能不能通要试**；失败会把上游原话显示出来。': '画像リクエストの形式は**各社のドキュメントどおり**です（`size` がピクセルか 1K/2K の段階か、参照画像の置き場所、`response_format` の要否がすべて異なります）—— 本機にはこれらのベンダーの Key がないため、**通るかどうかは試すしかありません**。失敗時は上流の文言をそのまま表示します。',
  '图形': '画像',
  '图形模型': '画像モデル',
  '图片文件已不在': '画像ファイルが見つかりません',
  '图生图专家': '画像編集の専門家',
  '在「生图」或「生视频」里生成一个，它会自动出现在这里。': '「画像生成」または「動画生成」で作成すると、ここに表示されます。',
  '在「设置 → 图像 / 视频模型」里可以添加别的模型。⚠️ 请求形状按各家的文档写（生图 / 生视频各一套：端点、参数名、轮询都不一样），**能不能通要试** —— 失败会把上游原话显示出来。': '「設定 → 画像 / 動画モデル」で別のモデルを追加できます。⚠️ リクエスト形式は各社のドキュメントどおりです（画像用と動画用で別々：エンドポイント・パラメータ名・ポーリングが異なります）。**通るかどうかは試すしかありません** —— 失敗時は上流の文言をそのまま表示します。',
  '在下面输入第一条消息。\nAgent 会在你的电脑上读写文件、执行命令。': '下に最初のメッセージを入力してください。\nAgent はあなたのコンピュータ上でファイルの読み書きやコマンドの実行を行います。',
  '在会话里直接说「帮我看当前屏幕 / 帮我打开某应用」即可使用；助手只在你下达指令时操作界面，不会自行乱点。': 'チャットで「今の画面を見て」「このアプリを開いて」と言うだけで使えます。アシスタントは指示があった時だけ操作し、勝手にタップしません。',
  '在工作区里生成的文件会出现在这里。\n{0}工作区：{1}': 'ワークスペースで生成されたファイルがここに表示されます。\n{0}ワークスペース：{1}',
  '在手机上画界面草图（Material 3），导出成给 AI 的描述（随包自带，打开即用）': 'スマホで UI スケッチ（Material 3）を描き、AI 向けの説明文に書き出せます（同梱・すぐ使えます）',
  '在手机上跑，不联网、不花额度': 'スマホ上で動作：通信も課金も不要',
  '在某一秒截一张图当封面（.jpg）': '任意の秒で 1 コマを切り出してカバー画像に（.jpg）',
  '在浏览器里打开它注册 / 登录，把 Key 复制回来，再点这一行的「填 Key」贴进来。': 'ブラウザで開いて登録／ログインし、キーをコピーして戻り、この行の「キー入力」を押して貼り付けてください。',
  '在电脑上双击 dsh-mobile 目录里的：\n\n  start-bridge.cmd      （启用 TLS，推荐）\n  start-bridge-ws.cmd   （明文，仅私有网络）\n  pair-phone.cmd        （生成配对码）\n': 'パソコンで dsh-mobile フォルダ内のこれをダブルクリックしてください：\n\n  start-bridge.cmd      （TLS 有効・推奨）\n  start-bridge-ws.cmd   （平文・プライベートネットワーク専用）\n  pair-phone.cmd        （ペアリングコードを生成）\n',
  '在虚拟屏里打开': '仮想ディスプレイで開く',
  '地址已经内置好了 —— 不用你填端点。': 'アドレスは組み込み済み —— エンドポイントを入力する必要はありません。',
  '地址或模型不存在：请检查 Base URL 是否写对（例如 LongCat 必须是 /openai/v1，漏掉 openai 就会 404）。': 'アドレスまたはモデルが存在しません：Base URL を確認してください（例：LongCat は /openai/v1 である必要があり、openai を省くと 404 になります）。',
  '域名解析失败：请检查 Base URL 有没有写错，以及当前网络能否上网。': 'ドメインの解決に失敗しました：Base URL の打ち間違いと、現在のネットワークがインターネットに接続できるかを確認してください。',
  '基于 DeepSeek Harness 的本地运行时，除模型接口外不依赖任何服务器。': 'DeepSeek Harness ベースのローカルランタイム。モデル API 以外はどのサーバにも依存しません。',
  '填 Key': 'Key を入力',
  '增量 {0}': '差分 {0}',
  '壁纸': '壁紙',
  '壁纸已换上。': '壁紙を適用しました。',
  '声音是**原样搬过去**的（不重新编码），存成 .m4a —— 安卓/苹果/电脑都能放。': '音声は**そのままコピー**され（再エンコードなし）、.m4a として保存されます —— Android / iPhone / PC どこでも再生できます。',
  '处理中…': '処理中…',
  '备注：卡在哪一步、哪里别扭、想改什么': 'メモ：どこで詰まったか、どこが気になったか、何を変えたいか',
  '备用 Key {0}（内容不显示）': 'バックアップ Key {0}（内容は表示しません）',
  '备用 Key（多账号）· 已添加 {0} 把': 'バックアップ Key（複数アカウント）· {0} 件追加済み',
  '复制': 'コピー',
  '复制 JSON': 'JSON をコピー',
  '复制下面这段，到「首页」的任意会话里发出去（把括号里的内容换成你的）。模型看到就会走这条流程。': '下のテキストをコピーして、「ホーム」の任意のセッションで送ってください（括弧の中はご自身の内容に）。モデルはこの流れに沿って進めます。',
  '复制公众号 ID': '公式アカウント ID をコピー',
  '复制日志路径': 'ログのパスをコピー',
  '复制起始指令': '開始プロンプトをコピー',
  '复制路径': 'パスをコピー',
  '外观': '外観',
  '外观与语言': '外観と言語',
  '多人协同，打造超级团队': '多人数で協力して、スーパーチームを作ろう',
  '多模态': 'マルチモーダル',
  '多模态模型"看图"靠它 —— 它是单独一个文件（几百 MB），所以下载时会跟本体一起下（清单里叫"伴生文件"）。少了下半截，模型就只能聊天、看不了图。': 'マルチモーダルモデルが「見る」ための部分で、独立したファイル（数百 MB）です。そのため本体と一緒にダウンロードされます（マニフェストでは「付随ファイル」）。欠けるとチャットはできても画像は見られません。',
  '多模态模型下完可以对话，但图片还发不进模型：App 目前只发纯文本。引擎其实已经带了看图能力，只差"启动时指一下视觉编码器"和"把图片发出去"这两处接线，后面版本补。': 'ダウンロード後もマルチモーダルモデルはチャットできますが、画像はまだ送れません（現状 App はテキストのみ送信）。エンジン側は既に視覚機能を備えており、「起動時に視覚エンコーダを指定する」と「画像を送り出す」の 2 か所を繋ぐだけです。後のバージョンで対応します。',
  '多模态（能看图）': 'マルチモーダル（画像を見られます）',
  '大': '大',
  '太多了，只显示最新的 {0} 个；更早的可在「资料库」里按文件看。': '多すぎるため最新の {0} 件のみ表示しています。それ以前のものは「ライブラリ」でファイルとして見られます。',
  '失败': '失敗',
  '套餐(token plan)': 'プラン(token plan)',
  '如实说明：App 里**看不了** .pptx 的样子（没有 Office 组件）。生成后在「资料库」里能找到它，用「用其它应用打开」交给手机上的 WPS / Office，或者直接分享出去。': '正直に言うと：このアプリ内では .pptx の見た目を**表示できません**（Office コンポーネントを同梱していないため）。生成後は「ライブラリ」にあります。「他のアプリで開く」でスマホの WPS / Office に渡すか、そのまま共有してください。',
  '如实说明：上游那几个 python 自检脚本（几何校验、drawio/mermaid 导入）**没有随包**（手机上没 python），所以那几步用不了；上游的 211 个示例图也没随包（省 4.4 MB）。画法规范在技能里是完整的。': '正直に：上流の python 自検スクリプト（幾何チェック、drawio/mermaid 取り込み）は**同梱していません**（スマホに python がないため）ので、その手順は使えません。上流のサンプル図 211 点も同梱していません（4.4 MB 節約）。描き方の規範はスキル内に完全にあります。',
  '如果提示"安装包里没有 assets/studio"，说明这一版没把APP界面设计台打进去，需要重新构建 App。': '「インストールパッケージに assets/studio がない」と表示される場合、この版にはアプリUIデザインスタジオが含まれていません。アプリを再ビルドしてください。',
  '如果要把它发出去/上架，注意商店对**AI 生成内容**的要求（标记、年龄分级），这块要你自己把握。': '配布やストア公開をするなら、ストアの**AI 生成コンテンツ**に関する要件（表示、年齢区分）に注意してください。ここはご自身で判断する部分です。',
  '子会话用哪个模型': '子セッションが使うモデル',
  '子智能体': '子エージェント',
  '字号': '文字サイズ',
  '存在系统安全存储，不会写进命令行': 'システムのセキュアストレージに保存され、コマンドラインには書き込まれません',
  '存好后在微信「扫一扫 → 右上角相册」里选这张图。': '保存後、WeChat の「スキャン → 右上のアルバム」でこの画像を選んでください。',
  '存相册没成功（{0}）。可以改用「复制公众号 ID」，或直接截屏这张二维码。': 'アルバムへの保存に失敗しました（{0}）。「公式アカウント ID をコピー」を使うか、この QR コードをスクリーンショットしてください。',
  '安全提醒：桥拥有你电脑的命令执行权。优先使用 Tailscale 私有网络，不要在公网上做端口转发，也不要把配对码或证书指纹发给别人。': 'セキュリティ上の注意：ブリッジはあなたのパソコンのコマンド実行権限を持ちます。Tailscale などのプライベートネットワークを優先し、公衆網でポート転送せず、ペアリングコードや証明書フィンガープリントを他人に送らないでください。',
  '安全连接失败': '安全な接続に失敗',
  '安装包所在的位置没有对系统开放（这是应用自身的配置问题，请把运行日志发给开发者）。': 'インストーラーのある場所がシステムに公開されていません（アプリ側の設定の問題です。実行ログを開発者にお送りください）。',
  '安装失败（没有更多信息）': 'インストールに失敗（詳細なし）',
  '安装插件': 'プラグインをインストール',
  '安装未知应用': '提供元不明のアプリをインストール',
  '安装（会弹出系统安装界面）': 'インストール（システムのインストール画面が開きます）',
  '完全不渲染 —— 唯一能彻底不看到英文思考的办法': 'まったく描画しません —— 英文の思考を完全に見ない唯一の方法',
  '完全在本机算出来的配音：**不用联网、不用任何 Key、免费**。代价要说清：① 第一次要**下一次模型**（31.5 MB，装好后占约 32 MB 磁盘）；② 音色**比云端机械**（多说话人离线模型就是这样）；③ 手机上的实际速度**还没在真机上量过**。': '完全に端末内で計算する吹き替え：**通信不要・Key 不要・無料**。代償もはっきり書きます：① 初回に**モデルのダウンロード**が必要（31.5 MB・導入後は約 32 MB）; ② 声は**クラウドより機械的**（多話者オフラインモデルでは普通）; ③ 実機での速度は**まだ計測していません**。',
  '官方 CLI 的默认音色': '公式 CLI のデフォルト音色',
  '官方直连。若你的 Key 是 Anthropic 协议的，端点要改成 https://api.deepseek.com/anthropic。': '公式への直結。Key が Anthropic プロトコルの場合は、エンドポイントを https://api.deepseek.com/anthropic に変更してください。',
  '定位': '位置情報',
