  '实测 {0} tok/s（首字 {1} ms），能用但偏慢': '実測 {0} tok/s（初回トークン {1} ms）。使えますがやや遅めです。',
  '实测 {0} tok/s，一句话要等十几秒，基本没法用': '実測 {0} tok/s。一文に十数秒かかり、実用は難しいです。',
  '实测完成：{0}': '実測完了：{0}',
  '实验通道 · OpenCode Zen（第三方通道）': '実験チャンネル · OpenCode Zen（第三者）',
  '审讯室': '取調室',
  '宿主返回失败': 'ホストが失敗を返しました',
  '对方的目标：听出他**真正**的问题，并在节目结束前让他自己说出来。如果时间到了他还没说出口，就按"这一夜没能留住他"收尾，不要硬圆。': '相手の目標：彼の**本当の**問題を聞き出し、番組が終わる前に本人の口から言わせること。時間切れで言えなかったなら、「その夜は彼を引き止められなかった」で締めてください。無理に丸めないこと。',
  '对方的目标：在 8 轮之内判断你到底有没有在说谎，然后说「我知道了」。到那一刻你必须给出真相（或者揭穿他的误判），然后这局结束。': '相手の目標：8ラウンド以内にあなたが嘘をついているかどうかを判断し、それから「わかりました」と言う。その瞬間、あなたは真実を明かす（または誤った判断を覆す）必要があり、そこでこの局は終わる。',
  '对方的目标：在氧气耗尽前做完三个决定（先修哪条线、要不要丢一个货舱、要不要叫醒同伴）。三个都定了这局就结束，你按结果给一个明确的结局。': '相手の目標：酸素が尽きる前に三つの決定を下す（どのラインを先に直すか、貨物室を切り離すか、仲間を起こすか）。三つとも決まればこの局は終わり、あなたは結果に応じて明確な結末を示す。',
  '对话已清空': '会話を消去しました',
  '对话生成': '対話生成',
  '对话缓存：省掉重算 {0} 次 · 整段重建 {1} 次': '会話キャッシュ：再計算を {0} 回省略・全体再構築 {1} 回',
  '对话缓存：还没开始对话': '会話キャッシュ：まだ会話していません',
  '对话越长越吃上下文：DSH 每轮光系统提示就要约 7k tokens，所以别选 4k（会一直报"上下文不够"）。越大越吃内存，服务和测速都用这个档位；改了要重启服务。': '会話が長いほどコンテキストを食います：DSH は 1 ターンごとにシステムプロンプトだけで約 7k トークン使うため、4k は選ばないでください（「コンテキスト不足」が続きます）。大きいほどメモリを食います。サービスと計測はこの設定を使います。変更後は再起動が必要です。',
