  '导入完成：新增 {0} 条，跳过 {1} 条重复或不合法的条目；另有 {2} 条因为超出 {3} 字节预算没有导入。': 'インポート完了：{0} 件を追加、{1} 件を重複または不正としてスキップ。さらに {2} 件が {3} バイトの予算を超えるため取り込めませんでした。',
