  '导出会把全部记忆（含分类、重要度、作用范围与总开关）存成一个 JSON 文件；导入按内容去重合并，**不会覆盖**已有条目。': 'エクスポートはすべての記憶（分類・重要度・適用範囲・全体スイッチを含む）を 1 つの JSON ファイルに保存します。インポートは内容で重複を除いて統合し、既存の項目を**上書きしません**。',
