  '小米 MiMo：**套餐与充值是两套端点**，用界面上的按钮切换（实测两套都真实存在）。': 'Xiaomi MiMo：**プランとチャージは別々のエンドポイント**です。画面上のボタンで切り替えてください（両方とも実在を確認済み）。',
