  '我们来玩一局「有目标的角色扮演」。\n\n【你演】{0}\n\n{1}\n\n【场景】{2}\n\n【目标与结束条件】{3}\n\n{4}\n\n现在开始：你先说第一句。': '「目標のあるロールプレイ」を一局やりましょう。\n\n【あなたが演じる】{0}\n\n{1}\n\n【場面】{2}\n\n【目標と終了条件】{3}\n\n{4}\n\nでは始めます：あなたが最初の一言を言ってください。',
