  '所有已注册的模型（点一下就进池子{0}）': '登録済みのモデル一覧（タップするとプール{0}に入ります）',
  '手上已有视频：剪一段 / 拼接 / 抽音频 / 抽一帧 / 压小（本机跑，不联网）': 'すでにある動画に対して：一部を切り出す / つなげる / 音を取り出す / 1 コマ切り出し / 小さくする（すべて本機・ネット不要）',
  '手上已经有视频之后的几刀：剪一段、把几段拼起来、把声音抽出来、截一张封面、压小一点好发出去。**全部在本机跑**（用随包的 ffmpeg），不联网、不花任何额度。除了「压小」和「精确剪」要重新编码，其余几刀都是几秒就完事、也不掉画质。': '動画がすでにあるときの数カット：一部を切り出す、何本かをつなげる、音を取り出す、カバーを 1 コマ切り出す、送れるように小さくする。**すべて本機で実行**します（同梱の ffmpeg を使用）—— ネット不要・枠も消費しません。「小さくする」と「正確に切る」だけが再エンコードで、残りは数秒で終わり画質も落ちません。',
