  '打开发布页': 'リリースページを開く',
  '打开后台操作台（虚拟屏 + 实时画面）': 'バックグラウンド操作台を開く（仮想ディスプレイ＋ライブ画面）',
  '打开后，**会话里的 AI 会自己去查资料**（用户 2026-10-15 选定的方案 B）：App 在建会话时给运行时挂一个 `AnySearch` 的 MCP 服务器，模型于是能搜网页、并把来源链接写进回答。\n\n**不用填 Key 也能搜** —— 匿名层就能用（只是限流低）；想要更稳的额度，可以用邮箱在 [anysearch.com](https://anysearch.com) 换一把免费 Key（可选，填在下面）。': 'オンにすると、**セッション内の AI が自分で調べます**（2026-10-15 に選んだ方案 B）：App はセッション作成時に `AnySearch` の MCP サーバーをランタイムへ装着し、モデルはウェブを検索して回答に参照リンクを書けます。\n\n**検索に Key は不要**です —— 匿名レイヤーがそのまま使えます（レート制限は低め）。より安定した枠が必要なら [anysearch.com](https://anysearch.com) でメール登録して無料 Key を取得してください（任意・下に貼り付け）。',
  '打开后，**会话里的 AI 可以"分人做事"**：把一块子任务交给另一个 agent 实例（**它有自己的上下文窗口**），干完只把结论拿回来 —— 主会话因此不会被中间过程撑爆，也能并行推进几件事。': 'オンにすると、**セッション内の AI が仕事を分担できます**：タスクの一部を別のエージェント実体（**独自のコンテキストウィンドウ**）に渡し、結論だけを受け取ります —— メインセッションが途中経過で膨らまず、同時並行もできます。',
  '打开后，App 会在本机起一个小小的**转发代理**，把请求按**官方 CLI 的样子**发到 OpenCode 的匿名免费额度，并把拿到的免费模型直接加进你的模型列表 —— **不用配置任何 Key**。\n\n⚠️ 只是想"不用 Key 就能聊"的话，**用上面那条（免 Key 免费模型）就好** —— 这条 Zen 通道自 2026-09-16 起被上游改过 6 次门禁，时好时坏（2026-10-16 本机实测又能用了，但它随时可能再变）；想知道此刻通不通，点下面的「通道自检」。': 'オンにすると、アプリは端末内に小さな**転送プロキシ**を起動し、リクエストを**公式 CLI の形**で OpenCode の匿名無料枠へ送り、取得した無料モデルをそのままモデル一覧に追加します — **Key の設定は不要**。\n\n⚠️ 「Key なしで話せればよい」だけなら、**上の項目（無料モデル・Key 不要）を使ってください** — この Zen チャネルは 2026-09-16 以降に 6 回ゲートが変わり、通ったり通らなかったりします（2026-10-16 の実機計測では再び使えましたが、いつまた変わるか分かりません）。今つながるか知りたいときは、下の「チャネル自己診断」を押してください。',
  '打开失败：{0}': '開けませんでした：{0}',
  '打开总开关后，在这里选择要交给 Agent 操作的应用。': 'メインスイッチを入れてから、エージェントに操作させるアプリを選びます。',
  '打开没成功：{0}': '開けませんでした：{0}',
