  '执行命令': 'コマンドを実行',
  '执行异常：{0}': '実行エラー：{0}',
  '执行环境被沙箱挡住了（Android 上不该出现）。\n下一步：回「设置 → 模型」随便切一次模型，App 会重写运行配置并补上「danger-full-access」，之后重发即可。': '実行環境がサンドボックスにブロックされています（Android では起きないはずです）。\n次の手順：「設定 → モデル」でどれか別のモデルに一度切り替えてください。アプリが実行設定を書き直し、「danger-full-access」を追加します。その後にもう一度送信するだけです。',
  '执行结束': '実行終了',
