  '扩展名是 .{0}，但内容里有 NUL 字节 —— 按文本渲染会是乱码，所以这里如实告诉你而不是硬渲染。\n（{1}）\n\n{2}': '拡張子は .{0} ですが、中身に NUL バイトがあります —— テキストとして描画すると文字化けするので、無理に描画せずそのままお伝えします。\n（{1}）\n\n{2}',
