  '把 {0} 加进池子「{1}」': '{0} をプール「{1}」に追加',
  '把**一本小说**改编成**一个能在浏览器里玩的游戏**。它不是"AI 自己玩"，也不是"AI 对战" —— 是一套有原著依据的改编流程：每一步都要引原文，最后要拿运行证据说话。': '**一冊の小説**を**ブラウザで遊べるゲーム**に変える流れです。「AI が自分で遊ぶ」ものでも「AI 対戦」でもなく、原作に根拠を置く改編ワークフローです。各段階で原文を引用し、最後は実行時の証拠で示します。',
  '把**每行一句话**当成一个镜头，拼成一条短剧：每镜一句配音、一张画面、一行字幕。想要每镜不同画面就打开下面那个开关（会用生图按该行文本画一张）。': '**1行＝1ショット**として、1本のショートドラマにまとめます：各ショットに1つの音声・1枚の画面・1行の字幕。ショットごとに違う画面が欲しい場合は下のスイッチをオンに（その行のテキストから画像生成します）。',
  '把一本小说改编成能在浏览器里玩的游戏（七个阶段）': '小説をブラウザで遊べるゲームにする（7段階）',
  '把一段**文稿**变成一条带配音和字幕的视频：自动分段 → 每段配音 → 字幕画在画面上 → 合成。适合口播、解说、知识分享。': '**原稿**を音声と字幕付きの動画にします：自動分割 → 各部分を音声化 → 字幕を画面に描画 → 合成。ナレーション・解説・知識共有向け。',
  '把一段动作描述生成短视频': '動作の説明から短い動画を作成',
  '把下面这些材料做成 8 页左右的工作汇报（材料我贴在后面）': '以下の材料を 8 枚程度の業務報告スライドにしてください（材料はこの後に貼ります）。',
  '把二维码存到相册': 'QR コードをアルバムに保存',
