  '把要念的稿子贴进来。例如：\n大家好，今天讲三个提高效率的小习惯……': '読む原稿を貼り付けてください。例：\nこんにちは。今日は効率を上げる小さな習慣を三つ紹介します……',
  '把这两个方案做成一页对比：左边 A 方案、右边 B 方案': 'この 2 案を 1 枚の比較スライドにしてください：左に A 案、右に B 案。',
