  '拼接': 'つなげる',
  '拼接**要求几段的画面/声音格式一致**（同一次拍摄的通常就行）。不一致时不会硬拼（硬拼的成品画面会中途变形），而是让你勾「参数不一致时重新编码」——那就慢了。': 'つなげるには**各クリップの映像・音声形式が同じ**である必要があります（同じ撮影なら通常問題なし）。違う場合は無理につながず（無理につなぐと途中で映像が崩れます）、「形式が違うときは再エンコード」にチェックするよう促します —— その分遅くなります。',
  '拿不到「运行环境」的下载信息（网络不通或更新源连不上），所以这次装不了运行环境。你可以稍后重试；也可以把 runtime.zip 放到这台手机的 {0} 目录下，再点一次「开始准备」。': '実行環境のダウンロード情報を取得できませんでした（ネットワーク不通、または更新元に接続できません）。今回は準備できません。しばらくして再試行するか、runtime.zip をこの端末の {0} フォルダに置いてから、もう一度「準備を開始」を押してください。',
  '拿到 {0} 个模型': '{0} 件のモデルを取得',
  '按 OpenAI 兼容形状发：size 用像素值，参考图放顶层 image 数组。': 'OpenAI 互換の形式で送ります：`size` はピクセル値、参照画像は最上位の `image` 配列に入れます。',
