  '掐头去尾，只留中间那一段（默认不重编码，几秒就完）': '前後を落として真ん中だけ残す（既定では再エンコードなし・数秒で完了）',
  '接口或**模型名已经退役**（名字换了就会这样）：回「设置 → 模型」点「获取模型」拉一份新的清单，重新勾选保存。': 'エンドポイントか**モデル名が廃止**されています（名前が変わるとこうなります）：「設定 → モデル」で「モデルを取得」を押して新しい一覧を取り、選び直して保存してください。',
