  '本': '本',
  '本 App 随包包含以下第三方组件：\n\n· ffmpeg 7.1（含 libx264）—— 用于口播/短剧的拼接、转码、混音、加字幕。以 GPLv2 或更高版本（GPLv2+）授权，因为启用了 libx264（GPL）。\n  许可全文：https://www.gnu.org/licenses/old-licenses/gpl-2.0.html\n  相应源码：https://ffmpeg.org/download.html 与 https://code.videolan.org/videolan/x264\n  本 App 未修改其源码，只做了针对 Android arm64 的编译（构建参数随仓库的 install/build-ffmpeg-android.sh 一并提供）。\n\n· frontend-design 与 discernment-nudge —— 两个随包「技能」（写给模型看的流程说明），搬自 Anthropic 官方开源技能库（github.com/anthropics/skills），以 Apache-2.0 授权。\n  本 App 已修改其文字：翻译成中文，并针对手机端的执行环境改写（本机没有 python；原版里"截图回看"这类做不到的步骤已删掉）。\n  许可全文随包提供：assets/skills/frontend-design/LICENSE.txt 与 assets/skills/discernment-nudge/LICENSE.txt\n  许可全文链接：https://www.apache.org/licenses/LICENSE-2.0\n\n· novel-to-game / novel-game-analyze / game-concept / game-world-design / game-art-direction / game-build / game-qa（七个随包技能）—— 来自 NovelToGame v0.4.0（zenstory.ai 的「有原著依据的小说改编游戏工作流」），以 MIT 授权。\n  本 App 只改写了两处：技能简介改写成一行中文、正文开头加署名区块；正文与参考文件一字未改。\n  许可全文随包提供：assets/skills/novel-to-game/LICENSE.txt\n\n· diagram-design —— 画图表技能（44 种图型，出自包含的 HTML + 内联 SVG），来自 diagram-design v2.6（github.com/cathrynlavery/diagram-design），以 MIT 授权。\n  本 App 只随包了必需部分（技能正文 + 方法文档 + 五套模板 + 图标）；上游的 211 个示例图与 5 个 python 脚本没有随包（原因写在技能正文的署名区块里）。\n  许可全文随包提供：assets/skills/diagram-design/LICENSE.txt\n\n· Android 运行时自带的系统组件（按 Android 系统许可）。\n· DeepSeek Harness 及各 dsh-* 子包（按各自许可）。': 'この App に同梱されている第三者コンポーネント：\n\n· ffmpeg 7.1（libx264 を含む）—— 口播／ショートドラマの連結・トランスコード・音声ミックス・字幕に使用。libx264（GPL）を有効にしているため GPLv2 以降（GPLv2+）で提供。\n  ライセンス全文：https://www.gnu.org/licenses/old-licenses/gpl-2.0.html\n  対応ソース：https://ffmpeg.org/download.html および https://code.videolan.org/videolan/x264\n  本 App はソースを改変しておらず、Android arm64 向けのビルドのみを行っています（ビルド引数はリポジトリの install/build-ffmpeg-android.sh に同梱）。\n\n· frontend-design と discernment-nudge —— 同梱の 2 つの「スキル」（モデルが読む手順書）。Anthropic 公式のオープンソース・スキル集（github.com/anthropics/skills）から取得し、Apache-2.0 で提供。\n  本 App はテキストを改変しています：中国語への翻訳と、端末の実行環境に合わせた書き換え（本機に python はなく、原版の「スクリーンショットで確認」等の手順は削除）。\n  ライセンス全文はパッケージ内に同梱：assets/skills/frontend-design/LICENSE.txt と assets/skills/discernment-nudge/LICENSE.txt\n  ライセンス全文リンク：https://www.apache.org/licenses/LICENSE-2.0\n\n· novel-to-game / novel-game-analyze / game-concept / game-world-design / game-art-direction / game-build / game-qa（同梱の 7 スキル）—— NovelToGame v0.4.0（zenstory.ai の「原作に根拠を置く小説→ゲーム化ワークフロー」）由来、MIT ライセンス。\n  本 App が変えたのは 2 点だけ：紹介文を 1 行の中国語にしたこと、本文の冒頭に出典表記を加えたこと。本文と参照ファイルは変更していません。\n  ライセンス全文はパッケージ内に同梱：assets/skills/novel-to-game/LICENSE.txt\n\n· diagram-design —— 図を描くスキル（44 種類、自己完結の HTML + インライン SVG）。diagram-design v2.6（github.com/cathrynlavery/diagram-design）由来、MIT ライセンス。\n  同梱したのは必要な部分だけ（SKILL.md + references/ + 5 種類のテンプレート + アイコン）。上流のサンプル図 211 点と python スクリプト 5 本は同梱していません（理由はスキル本文の出典表記に）。\n  ライセンス全文はパッケージ内に同梱：assets/skills/diagram-design/LICENSE.txt\n\n· Android ランタイム標準のシステムコンポーネント（Android システムライセンス）。\n· DeepSeek Harness と各 dsh-* サブパッケージ（それぞれのライセンス）。',
