  '本地模型服务没在运行：先回「本地大模型」页启动它，再回来聊。': 'ローカルモデルサービスが起動していません。「設定 → ローカル大規模モデル」で起動してから戻ってください。',
  '本地模型服务：{0}': 'ローカルモデルサービス：{0}',
