  '本地模型的上下文不够：这一轮要 {0} tokens，但只给了 {1}。\n下一步：打开「设置 → 本地大模型（测试）」，在「本地模型服务」里把上下文调大一档（推荐 16k），再重新启动服务。': 'ローカルモデルのコンテキストが足りません：このターンは {0} トークン必要ですが、{1} しかありません。\n次の手順：「設定 → ローカル大規模モデル（テスト）」を開き、「ローカルモデルサービス」でコンテキストを1段階上げて（16k 推奨）から、サービスを再起動してください。',
  '本地运行时 · 非云端账户': 'ローカルランタイム · クラウドアカウントではありません',
