  '本机 · {0}': 'この端末 · {0}',
  '本机**不能**自动截 WebView 的图（Android 上它是平台视图，截出来常常是空白），所以这里由你玩过之后逐项勾选 —— 这份记录就是证据。': '本機は WebView を**自動でスクリーンショットできません**（Android ではプラットフォームビューで、撮っても真っ白になることが多い）。そこで、遊んだあとに項目ごとにチェックしてください —— この記録が証拠になります。',
