  '本机工作区': 'この端末のワークスペース',
  '本机播放服务或 WebView 没建起来（原因见运行日志）。': 'ローカル再生サーバーまたは WebView を起動できませんでした（理由は実行ログをご覧ください）。',
  '本机操作桥没起来 —— 退出本页重进会自动拉起': 'ローカルブリッジが起動していません — このページを開き直すと自動で起動します',
  '本机模型不在这里 —— 本地模型只做简单对话，且它的入口已撤下，暂时没有界面能进入它。': 'ローカルモデルはここには出ません。簡単な会話専用で、入口も撤去ずみです（今は画面から開く方法がありません）。',
  '本机模型不能进轮换池 —— 它只在你手机上跑，轮换池是给云端模型排队用的。': '本機モデルはローテーションプールに入れられません —— スマホ上で動くもので、プールはクラウドモデルを順番に試すためのものです。',
  '本机模型不需要 API Key —— 如果看到这条，说明 App 注入本机凭据时出了问题（这是个 bug，请在「运行日志」里反馈这条消息）。': 'オンデバイスモデルに API キーは不要です。これが表示された場合、App がローカル認証情報を注入できていません（バグです。「実行ログ」からこのメッセージを報告してください）。',
  '本机模型需要 Android 9 或更高（当前系统较旧）': 'オンデバイスモデルには Android 9 以上が必要です（この端末は古い版です）',
  '本机现有的运行环境包：{0}': 'この端末にある実行環境パッケージ：{0}',
  '本机用户': 'この端末のユーザー',
  '本机离线配音写出了空文件，请再试一次。': '端末内吹き替えが空のファイルを出力しました。もう一度お試しください。',
  '本机离线配音失败：{0}': '端末内吹き替えに失敗：{0}',
  '本机离线配音的引擎没能加载（{0}）。可能是安装包不完整，或这台机器的架构不受支持 —— 可以改用系统 / MiMo / MiniMax。': '端末内吹き替えエンジンを読み込めませんでした（{0}）。インストールが不完全か、この端末の CPU アーキテクチャが非対応の可能性があります —— システム / MiMo / MiniMax に切り替えてください。',
  '本机离线配音的模型**已经装好**了（占约 32 MB，离线可用）。': '端末内吹き替えのモデルは**導入済み**です（約 32 MB、オフラインで動作）。',
  '本机离线配音的模型还没装好（{0}）。到「配音 → 本机离线」点一下下载即可。': 'オフライン吹き替えのモデルがまだ入っていません（{0}）。「吹き替え → 端末内」でダウンロードを押してください。',
  '本机离线配音的模型还没装（缺 {0}）。在「配音 → 本机离线」那里点下载即可（31.5 MB，装好后离线可用、不用 Key）。': '端末内吹き替えのモデルが未インストールです（不足: {0}）。「吹き替え → 端末内」でダウンロードしてください（31.5 MB・導入後はオフライン・Key 不要）。',
  '本机离线配音（2026-10-13 新增，随包）\n\n· sherpa-onnx 1.13.8 —— 本机离线配音的推理引擎（语音合成）。以 Apache-2.0 授权，https://www.apache.org/licenses/LICENSE-2.0\n  源码与文档：https://github.com/k2-fsa/sherpa-onnx\n  本 App 未修改其源码，直接用官方发布的 arm64 预编译库。\n\n· onnxruntime —— sherpa-onnx 的推理后端（随包的 libonnxruntime.so）。以 MIT 授权，源码：https://github.com/microsoft/onnxruntime\n\n· seek-bzip 2.0.0 —— 纯 JS 的 bzip2 解压（用来在手机上解模型压缩包，因为 Android 既没有 tar 也没有 bzip2）。以 MIT 授权，源码**原样**随包提供：assets/toolbox/vendor/seek-bzip/（含 LICENSE）\n\n· 语音模型 vits-icefall-zh-aishell3 —— **不随包**，由你在 App 里按需下载（约 32 MB）。它来自 icefall（Apache-2.0）（https://github.com/k2-fsa/icefall），基于 aishell3 数据集训练。下载前界面上会写明体积与来源。': '端末内オフライン吹き替え（2026-10-13 追加・同梱）\n\n· sherpa-onnx 1.13.8 —— 端末内吹き替えの推論エンジン（音声合成）。Apache-2.0 ライセンス、https://www.apache.org/licenses/LICENSE-2.0\n  ソースとドキュメント：https://github.com/k2-fsa/sherpa-onnx\n  本アプリはソースを改変せず、公式配布の arm64 用ビルド済みライブラリをそのまま使っています。\n\n· onnxruntime —— sherpa-onnx が使う推論バックエンド（同梱の libonnxruntime.so）。MIT ライセンス、ソース：https://github.com/microsoft/onnxruntime\n\n· seek-bzip 2.0.0 —— 純粋な JS による bzip2 解凍（Android には tar も bzip2 も無いため、端末上でモデルの圧縮ファイルを展開するのに使います）。MIT ライセンス。ソースは**改変せず同梱**：assets/toolbox/vendor/seek-bzip/（LICENSE 同梱）\n\n· 音声モデル vits-icefall-zh-aishell3 —— **同梱していません**。アプリ内で必要時にダウンロードします（約 32 MB）。icefall（Apache-2.0、https://github.com/k2-fsa/icefall）が aishell3 データセットで学習したものです。ダウンロード前にサイズと出所を画面に表示します。',
  '本机离线（零 Key）': '端末内（Key 不要）',
  '本机运行，不联网也能用': '端末内で動作。ネット接続なしでも使えます',
  '本次会话始终允许': 'このセッションでは常に許可',
  '本次请求内容过大（上传或上下文太长）。请精简后重试。': '今回のリクエストが大きすぎます（アップロードまたはコンテキストが長すぎます）。内容を減らして再試行してください。',
  '本次运行 · {0}': '今回の実行 · {0}',
