  '构建类型：{0}': 'ビルドタイプ：{0}',
  '架构图 / 流程图 / 时序图 / ER 图 / 时间线…（44 种，出自包含网页）': 'アーキテクチャ／フローチャート／シーケンス／ER／タイムライン…（44 種、自己完結の HTML）',
  '查看「哪个应用在用、用了多久」的能力。⚠️ 这一项没有「只看本应用」的页面：打开后是一份应用列表，要自己在里面找到本应用再允许。': 'どのアプリが使われているか・どれくらい使われたかを見る機能です。⚠️ この項目には「このアプリだけ」のページがありません：開くとアプリ一覧が出るので、その中から本アプリを見つけて許可してください。',
  '查看图文使用说明': '図解の使い方を見る',
  '查看源码': 'ソースを表示',
  '查看详情（链接已复制）': '詳細を見る（リンクをコピーしました）',
