  '校验没通过。': '検証に通りませんでした。',
  '样音已生成：{0}（去「资料库」里点一下就能听）': 'サンプルを作成しました：{0}（「ライブラリ」でタップすると再生できます）',
  '核心使命（来自插件原文）': 'コアミッション（プラグイン原文より）',
  '框的宽（微调）': '枠の幅（微調整）',
  '框的高（微调）': '枠の高さ（微調整）',
  '框：x={0} y={1} 宽 {2} 高 {3}（像素）—— 上面预览里那块就是真会被盖住的地方。': '枠：x={0} y={1} 幅 {2} 高さ {3}（ピクセル）—— 上のプレビューの部分が実際に覆われる場所です。',
  '桥启用证书时必须打开；需要填证书指纹': 'ブリッジで証明書を使う場合は必ずオンにしてください。証明書のフィンガープリントが必要です。',
  '桥已就绪：127.0.0.1:{0}（Agent 从 phone-agent.json 拿钥匙）': 'ブリッジ準備完了：127.0.0.1:{0}（Agent は phone-agent.json から鍵を読みます）',
  '桥未就绪（重启 App 会自动再拉起）': 'ブリッジは未準備です（アプリを再起動すると自動で立ち上がります）',
  '检查失败，原因不明。': '確認に失敗しました。原因は不明です。',
  '检查失败：{0}': '確認に失敗：{0}',
  '检查更新': '更新を確認',
  '检测失败：{0}': '検出に失敗しました：{0}',
  '模型': 'モデル',
  '模型"想"的那一段怎么显示（它的语言由模型决定）': 'モデルが「考える」部分の表示方法（言語はモデルが決めます）',
  '模型名不能为空。': 'モデル名は必須です。',
  '模型名不被该端点接受。请点「获取模型」从列表里选一个，别手填错名字。': 'このエンドポイントではこのモデル名を受け付けません。「モデルを取得」をタップして一覧から選んでください。手入力で名前を間違えないように。',
  '模型名要用控制台里的接入点/模型 id': 'モデル名はコンソールのエンドポイント／モデル id を指定してください',
  '模型名（发给上游的 id）': 'モデル名（上流に送る id）',
  '模型已在本会话生效，但**没能记住**（保存失败：{0}）。重启 App 后会回到原来的模型。': 'モデルはこのセッションでは有効ですが、**記憶できませんでした**（保存失敗：{0}）。アプリを再起動すると元のモデルに戻ります。',
  '模型已就绪': 'モデル準備完了',
  '模型已经登记好（{0} 个，会话里能选），但连通性测试没通过 —— 先按下面的原因排查，别急着在新会话里用它。': 'モデルは登録済みです（{0} 件、セッションで選択可）が、接続テストに通りませんでした — 下の原因を先に確認してください。新しいセッションで急いで使わないように。',
  '模型已经登记好（{0} 个，会话里能选），但连通性测试没通过 —— 见下面的原因。': 'モデルは登録済みです（{0} 件、セッションで選択可）。ただし接続テストに失敗しました —— 原因は下記をご覧ください。',
  '模型已配置。': 'モデルを設定しました。',
  '模型文件只是"权重"（一堆数字），真正算的是引擎。这一版随包的是 **LiteRT-LM**（跑 Gemma 4 那批 `.litertlm`）。其它格式（比如 `.gguf` 的 llama.cpp）**没有**编进包里，所以那些模型会显示「缺引擎」。缺引擎不是你的手机不行，是包里没有那个引擎；引擎一上，红就会变绿。': 'モデルファイルは「重み」（数字の集まり）にすぎず、実際に計算するのはエンジンです。このビルドに同梱しているのは **LiteRT-LM**（Gemma 4 の `.litertlm` 用）です。他の形式（例：llama.cpp の `.gguf`）は**パッケージに含まれていない**ため、それらのモデルは「エンジンなし」と表示されます。これは端末のせいではなく、単にエンジンが同梱されていないだけです。エンジンが入れば赤が緑になります。',
  '模型没有返回任何内容。': 'モデルが何も返しませんでした。',
  '模型没有返回可用文本：{0}': 'モデルが利用可能なテキストを返しませんでした：{0}',
  '模型清单': 'モデル一覧',
  '模型的 JSON 里没有 items 数组 —— 这次没提炼出结果。': 'モデルの JSON に items 配列がありません —— 今回は何も抽出できませんでした。',
  '模型的输出不是合法 JSON（{0}）': 'モデルの出力が有効な JSON ではありません（{0}）',
  '模型的输出解析失败：{0}': 'モデルの出力を解析できませんでした：{0}',
  '模型的输出里找不到 JSON 结构（前 120 字：{0}）': 'モデルの出力に JSON 構造が見つかりません（先頭 120 文字：{0}）',
  '模型的输出顶层既不是对象也不是数组。': 'モデルの出力は最上位がオブジェクトでも配列でもありません。',
