  '模型这边被限流了（429）。等一会儿再点，或换一个模型。': 'モデル側がレート制限中（429）。少し待つか、別のモデルに変えてください。',
  '模型选好了但还没填 Key 的话，从这里过去': 'モデルは選んだけど Key がまだなら、ここから',
  '模型配置': 'モデル構成',
  '模型配置变了（Key / 端点 / 模型清单），进程里的旧配置不会热更新，正在重建会话…': 'モデル構成が変わりました（Key / エンドポイント / モデル一覧）。プロセス内の古い構成はホットリロードされないため、セッションを再構築しています…',
