  '每镜生成一张新画面（按该行文本用生图）': 'ショットごとに新しい画面を生成（その行のテキストで画像生成）',
  '氧气还剩 40 分钟，而你也正在忘记事情': '酸素はあと40分、そしてあなたも物事を忘れはじめている',
  '汇总一份周报': '週報をまとめる',
  '池名': 'プール名',
  '池名不能为空 —— 这个名字会当成模型名显示在会话的模型面板里。': 'プール名は必須です —— この名前はセッションのモデルパネルにモデル名として表示されます。',
  '池名不能叫 rotate —— 这个名字被轮换代理自己占用了。': 'プール名に「rotate」は使えません —— この名前はローテーションプロキシが使用中です。',
  '池名只能用字母、数字和横线（例：cat、fast-1）。': 'プール名に使えるのは英数字とハイフンだけです（例：cat、fast-1）。',
  '池子在会话的模型面板里就是一项，名字就是池名（数据上是 `rotate/<池名>`）。': 'プールはセッションのモデルパネルに 1 項目として表示され、名前はプール名です（データ上は `rotate/<プール名>`）。',
  '池子里的顺序 = 尝试顺序：1 先试，失败了再试 2 …… 编辑成员时可以上移下移。': 'プール内の順序 = 試行順序：1 を先に試し、失敗したら 2 を試す…… メンバー編集時は上へ／下へ移動できます。',
  '没做成': 'できませんでした',
  '没取到免费模型 —— 上游那条通道可能暂时不可用（或这台机器上不了网）。': '無料モデルを取得できませんでした —— 上流の経路が一時的に使えないか、この端末がオフラインの可能性があります。',
  '没填内容，Key 未改动。': '入力がないため、Key は変更していません。',
  '没成功': '失敗しました',
  '没找到要存的二维码图片（assets/images/wechat_qr.png 不在包里），存相册这一步跳过了。': '保存する QR 画像が見つかりません（assets/images/wechat_qr.png が同梱されていません）。アルバムへの保存はスキップしました。',
  '没有匹配「{0}」的记忆。': '「{0}」に一致する記憶はありません。',
  '没有匹配的文件': '一致するファイルがありません',
  '没有可用的下载源': '利用できるダウンロード元がありません',
  '没有可用的内容。': '使える内容がありません。',
  '没有可自检的通道（先去「模型」里打开一个）。': 'セルフチェックできるチャンネルがありません（先に「モデル」で 1 つ有効にしてください）。',
  '没有可配音的文本。': '読み上げるテキストがありません。',
  '没有存 Key': 'Key が保存されていません',
  '没有找到可以剪的视频。\n这里列的是「作品」里生成过的视频 + 工作区里的视频；两个地方都空的话，先去「创作台 → 生视频」生成一段，或把视频放进工作区。': '切り取れる動画がありません。\nここには「作品」で生成した動画とワークスペース内の動画が並びます。どちらも空のときは、まず「スタジオ → 動画を生成」で作るか、動画をワークスペースに入れてください。',
  '没有拿到失败原因，下面是脚本的原话：': '失敗理由を取得できませんでした。以下はスクリプトの生の出力です：',
  '没有提炼出内容': '何も抽出できませんでした',
  '没有访问该模型的权限（可能是套餐不含、或 Key 权限受限）。': 'このモデルへのアクセス権がありません（プランに含まれていない、または Key の権限が制限されている可能性があります）。',
  '没有识别到内容（可能没说话、或识别服务临时失败）。可以重试，或先用文字输入。': '内容を認識できませんでした（話していない、または認識サービスが一時的に失敗した可能性があります）。再試行するか、文字入力をお使いください。',
  '没有读到内容': '内容を読み取れませんでした',
  '没有选中任何文件': 'ファイルが選択されていません',
  '没有配置 MiMo（小米）的 API Key，无法配音。请在「设置 → 云端大模型 → MiMo」里填一个 Key，或改用系统配音。': 'MiMo（小米）の API Key が未設定のため音声合成できません。「設定 → クラウドモデル → MiMo」で Key を入力するか、端末の音声に切り替えてください。',
  '没有配置 MiniMax 的 API Key，拉不到音色列表。请在「设置 → 云端大模型 → MiniMax」里填一个 Key。': 'MiniMax の API Key が未設定のため音色一覧を取得できません。「設定 → クラウドモデル → MiniMax」で Key を入力してください。',
  '没有配置 MiniMax 的 API Key，无法配音。请在「设置 → 云端大模型 → MiniMax」里填一个 Key，或改用系统配音。': 'MiniMax の API Key が未設定のため音声合成できません。「設定 → クラウドモデル → MiniMax」で Key を入力するか、端末の音声に切り替えてください。',
  '没法给「{0}」登记任何模型，所以没有保存成功：自动拉取失败，这家也没有内置建议模型。请点「获取模型」自己勾选，或到「添加模型」里手填 model id。': '「{0}」に登録できるモデルが1つもなかったため、保存できませんでした：自動取得に失敗し、このサービスには内蔵の推奨モデルもありません。「モデルを取得」で自分で選ぶか、「モデルを追加」で model id を手入力してください。',
  '没能唤起微信（{0}），可以自己打开微信扫一扫。': '微信を起動できませんでした（{0}）—— ご自身で微信のスキャンを開いてください。',
  '没能唤起微信（可能是没装微信，或这条指令被别的应用接管了）—— 可以自己打开微信扫一扫再扫这张图。': 'WeChat を起動できませんでした（インストールされていないか、このコマンドを別のアプリが引き受けています）—— ご自分で WeChat のスキャンを開いてこの画像を読み取ってください。',
  '没能完成': '完了できませんでした',
  '没能打开「{0}」的设置页。手动找：{1}': '「{0}」の設定ページを開けませんでした。手動で開く：{1}',
  '没能打开系统设置页': 'システム設定ページを開けませんでした',
  '没能把会话跑起来。常见原因：模型还没配好、网络不通，或者本机模型服务已经停了。改完之后点「重试」；下面的报文是给开发者看的原始信息。': 'セッションを起動できませんでした。よくある原因：モデルが未設定、ネットワーク不通、オンデバイスモデルサービスの停止。直したら「再試行」を押してください。下の文面は開発者向けの生のメッセージです。',
  '没能读到工作区目录里的文件。\n{0}\n\n点右上角刷新重试。': 'ワークスペースディレクトリのファイルを読み取れませんでした。\n{0}\n\n右上の更新をタップして再試行してください。',
  '没能读到这条会话的历史记录（会话文件可能已被清理，或解码失败）。模型的上下文仍然在，直接接着问就行。': 'このセッションの履歴を読み取れませんでした（セッションファイルが削除されたか、デコードに失敗した可能性があります）。モデルのコンテキストは残っているので、そのまま続けて質問できます。',
  '没装上：{0}': '導入できませんでした：{0}',
  '没通：{0}': '不通：{0}',
