  '泡泡猫助手': 'パオパオキャットアシスタント',
  '泡泡猫已就绪，可以后台帮你搜索、比价、查信息': 'パオパオキャット準備完了：バックグラウンドで検索・価格比較・情報検索ができます',
  '泡泡猫的DSH': '泡泡猫的DSH',
