  '泡泡猫规则库': 'パオパオキャット ルールライブラリ',
  '泡泡猫规则库（录制 + 分享）': 'パオパオキャット ルールライブラリ（録画＋共有）',
  '泡泡猫（点一下它会说话）': 'パオパオ猫（タップすると喋ります）',
  '流畅运行': '快適に動作',
  '浅色': 'ライト',
  '浅色：白底玻璃面板 + 青紫点缀，白天和强光下看得清。深色：同一套强调色的深色面，面板换成更亮的半透明层，夜里不刺眼。像素：近黑底 + 高饱和的薄荷/洋红/琥珀，并且**圆角全部变成直角**（不只是换色）。': 'ライト：白いガラス面＋シアン／紫のアクセントで、昼間や明るい場所でも読みやすい。ダーク：同じアクセントを暗い面に載せ、パネルは明るい半透明に —— 夜でも眩しくない。ピクセル：ほぼ黒の下地に高彩度のミント／マゼンタ／アンバー、さらに**角丸がすべて直角になります**（色替えだけではありません）。',
  '测一下': 'テスト',
