  '添加附件': '添付を追加',
  '清单按「内存 + 芯片」挑文件：芯片命中就下 NPU 专属版，否则用通用版。': 'リストは「メモリ＋チップ」でファイルを選びます。チップが一致すれば NPU 専用版、なければ汎用版を使います。',
  '清单载入失败：{0}': 'リストの読み込みに失敗：{0}',
  '清单里写的包大小大得不像话（{0}），不下。': 'マニフェストに書かれたサイズが大きすぎます（{0}）。ダウンロードしません。',
  '清单里的 sha256 还没回填时，只能校验文件大小；回填后才会逐字节校验。': 'sha256 が未記入の間はファイルサイズのみ検証されます。記入後はバイト単位で検証します。',
  '清单里缺少 {0} 的文件大小，无法校验': 'マニフェストに {0} のファイルサイズがないため、検証できません',
  '清晰度': '解像度',
  '清晰度 CRF（越大越糊越小）': '画質 CRF（大きいほど粗く小さく）',
  '清空全部': 'すべて削除',
  '清空全部记忆？': 'すべての記憶を削除しますか？',
  '清空对话': '会話を消去',
  '清空搜索': '検索をクリア',
  '清除': '削除',
  '清除失败：{0}': '削除に失敗：{0}',
  '游戏页面加载失败：{0}': 'ゲームページの読み込みに失敗しました：{0}',
  '源码模式 · {0}': 'ソースモード · {0}',
  '点一下 = 在虚拟屏里点那个坐标；按住拖动 = 滑动。画面每 0.5 秒刷新一次。': 'タップ＝仮想画面のその位置をタップ、ドラッグ＝スワイプ。画面は0.5秒ごとに更新。',
  '点一下「创作台 · 生图」，我给你画一张。': '「スタジオ · 画像生成」をタップすれば一枚描いてあげるよ。',
  '点一下立即生效，重启后保持': 'タップするとすぐ反映され、再起動後も保持されます',
  '点一条 → 带着对应技能的指令开新会话': '1 つタップ → 対応するスキルの指示付きで新しいセッションを開始',
  '点下面按钮后会打开系统的「保存文件」界面：存到哪儿由你决定（一般是"下载"目录）。': '下のボタンを押すとシステムの「ファイルを保存」画面が開きます。保存先は自由です（通常は「ダウンロード」フォルダ）。',
  '点下面的「获取模型」可以直接勾选。': '下の「モデルを取得」から直接選択できます。',
  '点下面的按钮**直接开一个新会话**（首句就是这段起始指令）；也可以自己复制走，发到任意会话里。': '下のボタンで**すぐに新しいセッションを開けます**（最初のメッセージがこの指示文です）。コピーして任意のセッションに送ることもできます。',
  '点击展开会话': 'タップしてセッションを展開',
  '点厂家名字展开：介绍 → 去注册 → 获取模型 → 填 Key → 测试并保存': 'プロバイダ名をタップして展開：紹介 → 登録 → モデル取得 → Key 入力 → テストして保存',
  '点右上角 + 新建：设定时间后，到点会自动跑一次对话任务。': '右上の + で新規作成：時間を設定すると、その時刻に会話タスクが自動で実行されます。',
  '点右上角「新建工作区」建一个；工作区就是 DSH 运行的工作目录。': '右上の「新しいワークスペース」で作成できます。ワークスペースは DSH が動作する作業ディレクトリです。',
  '点底部的输入框开始一次对话，会话会出现在这里；本机历史会话由 DSH 的会话文件提供。': '下部の入力欄をタップして会話を始めると、セッションがここに表示されます。本機の履歴セッションは DSH のセッションファイルから取得します。',
  '版本': 'バージョン',
  '版本 {0}{1}{2}：{3}（点一下{4}）': 'バージョン {0}{1}{2}：{3}（タップで{4}）',
  '特大': '特大',
  '特殊权限（必须去系统页面手动打开，应用无法自行授予）': '特別な権限（システム画面で手動で有効にする必要があります。アプリからは許可できません）',
  '状态：代理在跑（127.0.0.1:{0}）· 免费模型 {1} 个{2}': '状態：プロキシ稼働中（127.0.0.1:{0}）· 無料モデル {1} 件{2}',
  '状态：代理没在跑': '状態：プロキシは動作していません',
  '状态：读取中…': '状態：読み込み中…',
  '现在一个模型都没有，开始会话也没法回话。\n\n去「设置 → 模型」：选一家服务商（端点会自动填好），填上你的 API Key，点「测试并保存」。通过之后回到首页就能开始了。': '今はモデルが1つもないため、セッションを始めても答えられません。\n\n「設定 → モデル」へ：サービスを選び（エンドポイントは自動入力されます）、API Key を入力して「テストして保存」を押してください。通ればホームに戻れば始められます。',
  '现在用你填的这一条。清空后保存就回到内置的两条源。': '入力した更新元を使用中です。空にして保存すると内蔵の 2 つに戻ります。',
  '现在用内置的两条源（GitHub 原站为主、jsDelivr 兜底），**一般不用动**。如果这两条在你那边连不上，把你自己的镜像地址填进来。': '内蔵の 2 つの更新元（GitHub を主、jsDelivr を予備）を使用中です。**通常は変更不要**です。どちらもつながらない場合は、ご自分のミラーアドレスを入力してください。',
  '现在还不能"看图"': '現時点では「画像を見る」ことはできません',
  '现在这个模型属于「{0}」，但那一家的 API Key 还没配，所以调不通。\n下一步：打开「设置 → 模型」，把这一家的 Key 填上（Agnes 可以到 platform.agnes-ai.cn 免费注册拿 Key），保存后回到会话重发一次。': '現在このモデルは「{0}」に属していますが、そのプロバイダの APIキーが未設定のため呼び出せません。\n次の手順：「設定 → モデル」を開き、このプロバイダの Key を入力してください（Agnes は platform.agnes-ai.cn で無料登録して Key を取得できます）。保存したらセッションに戻って再送信してください。',
  '生图': '画像',
  '生图/生视频经常遇到 429（限流）或排队时，多一把 Key 就能在被限流时**自动换另一把**继续。注意：限流按**账号**算 —— **同一个账号**多建几把 Key 共享同一份配额，加了也没用，必须是**另一个账号**的 Key。': '画像/動画生成で 429（レート制限）や待ち行列が頻発するとき、Key をもう1つ持っておくと、制限中は**自動でもう一方に切り替え**て続行できます。注意：レート制限は**アカウント単位**です —— **同じアカウント**で複数作っても同じ割り当てを共有するので効果はなく、**別アカウント**の Key が必要です。',
  '生图模型': '画像モデル',
  '生图用': '画像生成',
  '生图用哪个模型？': '画像生成に使うモデルは？',
  '生成一张图片': '画像を生成する',
  '生成一段视频': '動画を生成する',
  '生成交接笔记（插进输入框）': '引き継ぎメモを生成（入力欄に挿入）',
  '生成口播视频': 'ナレーション動画を生成',
  '生成后打开系统分享面板（微信 / QQ / 文件传输助手 / 邮件都行）': '生成後にシステムの共有パネルを開きます（WeChat / QQ / ファイル転送 / メールなど）',
  '生成图像与视频': '画像と動画',
