  '生成好了，已放进「作品」。': '完成しました。「作品」に入れました。',
  '生成学习卡片': '学習カードを作る',
  '生成并{0}': '生成して{0}',
  '生成报告失败（运行日志还没初始化）。': 'レポートを生成できません（実行ログがまだ初期化されていません）。',
  '生成日志失败：{0}': 'ログの生成に失敗しました：{0}',
  '生成日志失败：拿不到 App 私有目录，无法落盘。': 'ログの生成に失敗しました：アプリのプライベートディレクトリを取得できず、保存できません。',
  '生成日志文件并选择保存位置（系统「保存文件」，零权限）': 'ログファイルを生成して保存先を選択（システムの「ファイルを保存」、権限不要）',
  '生成真正的 .pptx（不是 HTML 糊弄）': '本物の .pptx を生成（HTML でごまかさない）',
  '生成真正的 .pptx：12 种版式 + 自动排版（封面 / 卡片 / 时间线 / 对比 / 数据图…）': '本物の .pptx を生成：12 種類のレイアウト＋自動組版（表紙／カード／タイムライン／比較／データ図…）',
  '生成短剧视频': 'ショートドラマ動画を生成',
  '生成视频': '動画を生成',
  '生视频': '動画',
  '生视频模型': '動画モデル',
  '生视频用': '動画生成',
  '生视频用哪个模型？': '動画生成に使うモデルは？',
  '用 code-tool 技能帮我写一个小工具并跑通。需求：\n（说清输入是什么、要输出什么；我会写成 node 脚本、真的执行一次、把结果给你）': 'code-tool スキルで小さなツールを書いて、実際に動かしてください。要件：\n（入力が何で、出力が何かを書いてください。node スクリプトを書いて一度実際に実行し、結果をお渡しします）',
  '用 data-analysis 技能帮我分析数据。数据文件在：\n（把文件路径或工作区文件名写在这里；我要看结论、关键数字和图表）': 'data-analysis スキルでデータを分析してください。データファイル：\n（ファイルの保存先か、ワークスペース上のファイル名を書いてください。結論・重要な数字・グラフが欲しいです）',
  '用 diagram-design 技能，': 'diagram-design スキルで、',
  '用 doc-digest 技能帮我速读这份长文：\n（给出文件路径或粘贴内容；我要要点清单和一条时间线）': 'doc-digest スキルでこの長文を速読してください：\n（ファイルの保存先か本文を貼り付けてください。要点のリストと年表が欲しいです）',
  '用 doc-processing 技能帮我处理这份文档：\n（写清文件路径与你要的结果：摘要、改写、纠错，还是转成 Markdown/HTML）': 'doc-processing スキルでこの文書を処理してください：\n（ファイルの保存先と、欲しい結果を書いてください：要約・書き直し・校正・Markdown/HTML への変換など）',
  '用 file-organize 技能帮我整理工作区文件。目标：\n（说明按什么规则重命名或归档；动手前我会先把计划列给你确认）': 'file-organize スキルでワークスペースのファイルを整理してください。目的：\n（どの規則でリネーム・アーカイブするかを書いてください。実行前に必ず計画を出して確認を取ります）',
  '用 make-image 技能帮我生成一张图片。画面描述：\n（写清主体、场景、风格、光线；我会直接生成图片文件并告诉你路径）': 'make-image スキルで画像を生成します。画面の説明：\n（被写体・場面・スタイル・光を書いてください。画像ファイルを直接生成し、保存先をお知らせします）',
  '用 make-slides 技能帮我做一份幻灯片。': 'make-slides スキルでスライドを作ってください。',
  '用 make-slides 技能帮我做一份幻灯片。主题/材料：\n（把主题或要讲的内容写在这里，我先按你说的整理大纲，再生成 .pptx 文件并告诉你路径）': 'make-slides スキルでスライド資料を作ってください。テーマ／素材：\n（テーマや話したい内容をここに書いてください。まず構成を整理し、そのうえで .pptx を生成して保存先をお知らせします）',
  '用 make-video 技能帮我生成一段视频。画面描述：\n（写清主体、动作、镜头、时长；我会提交任务并等它生成好，然后给你文件路径）': 'make-video スキルで動画を生成します。画面の説明：\n（被写体・動き・カメラ・長さを書いてください。タスクを投入し、生成完了まで待ってからファイルの保存先をお知らせします）',
  '用 novel-to-game 技能把我这本小说做成一个能玩的游戏：\n（给出小说文件路径或书名。我会先拆原著、再比选方向，然后一步步做出能真跑的网页游戏 —— 这是一条多轮流水线，不是一轮就能交付的）': 'novel-to-game スキルで私の小説を遊べるゲームにしてください：\n（小説の保存先か書名をください。まず原作を分解し、方向性を比較してから、実際に動く Web ゲームを順に作ります —— 何ターンもかかる工程で、一度では納品できません）',
  '用 sheet-cleanup 技能帮我整理这张表：\n（给出 CSV 路径；说明要去重、统一格式，还是要按某列分组汇总）': 'sheet-cleanup スキルでこの表を整理します：\n（CSV の保存先を書いてください。重複削除か、表記の統一か、特定の列でのグループ集計かを指定してください）',
  '用 study-cards 技能把这些材料变成学习卡片：\n（给出文件路径或主题；我要「问题 / 答案」成对的卡片，能直接背）': 'study-cards スキルでこの教材を学習カードにします：\n（ファイルの保存先かテーマをください。「問い／答え」が対になった、そのまま暗記できるカードが欲しいです）',
  '用 translate-polish 技能帮我翻译并润色：\n（给出原文或文件路径，说明目标语言与语气；我要双语对照版）': 'translate-polish スキルで翻訳と推敲をします：\n（原文かファイルの保存先、目標言語とトーンを指定してください。対訳版をお渡しします）',
  '用 weekly-report 技能帮我写一份周报。时间范围与关注点：\n（比如"这周做的三件事"；我会先看工作区里的文件再汇总，不确定的地方会问你）': 'weekly-report スキルで週報を書きます。期間と注目点：\n（例：「今週やった三つのこと」。ワークスペースのファイルを先に見てまとめます。不明な点は質問します）',
  '用其它应用打开': '他のアプリで開く',
  '用周围像素把它盖住 —— **不是恢复原内容**。纯色、平滑背景效果好；复杂纹理背景会看出痕迹。': '周囲の画素で覆うだけで、**元の内容を復元するものではありません**。単色やなめらかな背景はきれいですが、複雑な模様の背景では跡が残ります。',
  '用哪个图像模型？': 'どの画像モデルを使いますか？',
  '用哪个文本模型？': 'どのテキストモデルを使いますか？',
  '用哪个视频模型？': 'どの動画モデルを使いますか？',
  '用户级': 'ユーザーレベル',
  '用手机上的播放器打开': 'スマホのプレーヤーで開く',
  '用手机自带的语音朗读：零配置、免费、可离线。⚠️ **但不是每台手机都装了语音引擎或中文语音包** —— 遇到"没有可用的文字转语音引擎"时，下面两条路任选：① 去系统设置里装一个引擎并下载中文语音包；② 改用 MiMo 或 MiniMax（都要一个 API Key，见下）。': '端末内蔵の読み上げを使います：設定不要・無料・オフライン可。⚠️ **ただし、すべての端末に音声エンジンや中国語の音声データが入っているわけではありません** ——「利用できる音声合成エンジンがありません」と出たら、下の二つのどちらかにしてください：① システム設定でエンジンを入れ、中国語の音声データをダウンロードする；② MiMo か MiniMax に切り替える（どちらも API Key が必要・下記参照）。',
  '申请失败：{0}': '申請に失敗しました：{0}',
  '申请常用权限': '一般的な権限をリクエスト',
  '申请日历权限': 'カレンダーの権限を申請',
  '电影感': 'シネマ',
