  '画一张 ER 图：用户、订单、商品三张表以及它们的关系': 'ER 図を描いて：ユーザー・注文・商品の3テーブルとその関係',
  '画一张系统架构图：调用方 → 网关 → 三个后端服务 → 数据库': 'システム構成図を描いて：呼び出し元 → ゲートウェイ → バックエンド3つ → データベース',
  '画一张项目时间线（甘特）：需求、开发、测试、上线四段': 'プロジェクトのタイムライン（ガント）を：要件・開発・テスト・リリースの4段階',
