  '画面比例': '画面比率',
  '留空 = 不改动已存的 Key': '空欄 = 保存済みの Key を変更しない',
  '留空 → 会生成 provider id「{0}」（中文名推不出字母，所以自动编号）': '空欄 → provider id「{0}」を生成します（中国語の名前は英字にできないため自動採番）',
  '留空就按厂家名生成，例如 qwen': '空欄にするとプロバイダ名で生成されます（例：qwen）',
  '白桦': '白桦',
  '盘上有 {0} 个模型本版跑不了：{1}。它们要 llama.cpp 引擎，而这个引擎 0.47 起就不随包了 —— 回「本地大模型」页可以删掉，或下载 Gemma 4 这类 .litertlm 模型': '端末上に {0} 個のモデルがこの版では動きません：{1}。これらは llama.cpp エンジンが必要ですが、そのエンジンは 0.47 以降同梱されていません。「ローカル大規模モデル」ページで削除するか、Gemma 4 のような .litertlm モデルをダウンロードしてください。',
  '直接就能用，不用填 Key。': 'そのまま使えます。Key は不要です。',
  '直接问它就好（这里没有工具、没有技能，纯聊天）。': 'そのまま聞いてください（ここにはツールもスキルもなく、純粋な会話です）。',
  '相册': 'アルバム',
  '看看卡在哪一步': 'どこで止まったか見る',
  '真实行为（本地轮换代理）：按池子里的顺序依次尝试，只有上游失败（429 限流 / 5xx / 连不上 / 等响应头等到超时）才换下一个 —— 流式响应一旦开始下发就不再切换（HTTP 响应头已经发出去，这是协议本身的约束，不是偷懒）；全部成员都失败，才会把错误抛回会话。它还会记住每个池子"上次成功"的那个成员，下次先从它开始试。': '実際の動作（ローカルローテーションプロキシ）：プールの順に試し、上流が失敗したとき（429 制限 / 5xx / 接続不可 / 応答ヘッダ待ちのタイムアウト）だけ次に移ります — ストリーミング応答が始まったらもう切り替えられません（HTTP ヘッダは既に送信済みで、これはプロトコルの制約であり手抜きではありません）。全メンバーが失敗したときだけ、エラーをセッションに返します。各プールの「前回成功した」メンバーも記憶し、次回はそこから試します。',
  '知识库': 'ナレッジベース',
  '知识库 {0} 段': 'ナレッジベース {0} 件',
  '知识库「{0}」的索引还是旧切法建的：它把好几篇不相关的文章塞在同一块里，检索会不准 —— 新的相关度门槛对它也无效。去知识库页点「重建（推荐）」就好（在本机重建，不联网、不花额度）。': 'ナレッジ「{0}」の索引は旧方式で作られています：無関係な記事を同じブロックにまとめてしまうため検索が不正確で、新しい関連度しきい値も効きません。ナレッジページの「再構築（推奨）」を押してください（端末内で再構築、通信も課金も不要）。',
  '知识库内容来自第三方社区语料，依 CC BY-SA 4.0 许可使用。': 'ナレッジの内容は第三者のコミュニティコーパス由来で、CC BY-SA 4.0 ライセンスで利用しています。',
  '知识库是给本地模型查的离线资料 —— 查到的片段会折进「本地对话」那一轮的问题里，所以它不联网、不花额度。': 'ナレッジベースはローカルモデルが調べるオフライン資料です。該当する断片は「ローカル会話」のそのターンの質問に織り込まれるため、通信も課金も不要です。',
  '知道了': '了解',
  '短剧': 'ショートドラマ',
  '短剧剧本专家': 'ショートドラマ脚本の専門家',
  '硅基流动没有时长参数：时长由模型决定，分辨率按比例换算成 image_size。': 'SiliconFlow には長さパラメータがありません：長さはモデルが決め、解像度は比率から `image_size` に換算されます。',
  '确定删除「{0}」吗？': '「{0}」を削除しますか？',
  '确定删除「{0}」吗？会释放 {1}': '「{0}」を削除しますか？{1} が解放されます。',
  '确定删除「{0}」？': '「{0}」を削除しますか？',
  '磁盘历史会话 {0} 条': 'ディスク上の履歴セッション {0} 件',
  '磁盘历史会话 {0} 条（其中 {1} 条是空会话，没列出来）': 'ディスク上の履歴セッション {0} 件（うち {1} 件は空のセッションのため非表示）',
  '磁盘历史会话：未读取': 'ディスク上の履歴セッション：未読み込み',
  '移出这个池子': 'このプールから外す',
  '移动文件': 'ファイルを移動',
  '移除': '取り除く',
  '移除这张图': 'この画像を削除',
  '空会话': '空セッション',
  '空闲 · {0} 条': 'アイドル · {0} 件',
  '立即运行一次': '今すぐ 1 回実行',
  '端口': 'ポート',
  '端口必须是数字': 'ポートは数字で入力してください',
  '端点': 'エンドポイント',
  '端点与其他厂商不同（/paas/v4）': 'エンドポイントが他社と異なります（/paas/v4）',
  '端点已切到「{0}」：{1}': 'エンドポイントを「{0}」に切り替えました：{1}',
  '端点是 /zen/go/v1（免费那档是 /zen/v1，两个别混）。「获取模型」拉的是这个端点的实时清单（实测约 37 个），里面**含免费模型**（如 beam-free、longcat-2.5-preview-free）——所以看到 *-free 不用吃惊，它们确实属于这档。若某个模型报「没有访问该模型的权限」，那是你这把 Key 在该模型上的权限问题，不是 Key 坏了。': 'エンドポイントは /zen/go/v1（無料枠は /zen/v1、混同しないでください）。「モデルを取得」はこのエンドポイントのリアルタイム一覧を取ります（実測 約 37 個）で、その中に**無料モデルが含まれます**（例：beam-free、longcat-2.5-preview-free）——ですので *-free という名前を見ても驚かないでください。本当にこの枠のモデルです。あるモデルで「このモデルへのアクセス権限がありません」と出た場合、それはこの Key のそのモデルに対する権限の問題で、Key が壊れているわけではありません。',
  '端点（这家有两套，点一下切换；选错会 401/404）': 'エンドポイント（この提供元は2種類。タップで切り替え。選び間違えると 401/404 になります）',
  '第 {0} 号': '話者 {0} 番',
  '第 {0} 镜的字幕帧没渲染出来。': '{0} ショットの字幕フレームを描画できませんでした。',
  '第 {0} 镜的画面没生成出来。': '{0} ショットの画面が生成できませんでした。',
  '第 {0} 镜起**跳过配音**（{1}）—— 改成"画面 + 字幕"的静音片继续做完，后面每一镜都不再尝试配音。': 'ショット {0} 以降は**吹き替えをスキップ**（{1}）—— 「映像＋字幕」の無音版として最後まで作ります。以降のショットでは再試行しません。',
  '第一次用建议：选一个 → 启动 →【测速】，再换另一个测一次，哪个 tok/s 高就用哪个。切换要重启服务，所以跑着的时候按钮是灰的。': '初回の目安：片方を選ぶ → 起動 →［計測］、もう片方に切り替えてまた計測し、tok/s が高い方を使ってください。切り替えにはサービスの再起動が必要なため、実行中はボタンが押せません。',
  '第三方组件与许可': 'サードパーティ製コンポーネントとライセンス',
  '等待当前轮次结束或先取消…': '現在のラウンドが終わるのを待つか、先にキャンセルしてください…',
  '等模型回复超时了，再点一次试试。': 'モデルの応答がタイムアウトしました。もう一度押してください。',
  '等第一帧…（把 App 拉到虚拟屏后才有画面）': '最初のフレームを待っています…（アプリを仮想ディスプレイに起動すると画面が出ます）',
  '等配音超时了（{0} 秒）。再试一次，或把文稿拆短些。': '音声の待機がタイムアウト（{0} 秒）。再試行するか原稿を短く分割してください。',
  '签名与当前应用一致，可以安装。': '署名は現在のアプリと一致しています。インストールできます。',
  '签名校验没通过。': '署名の検証に通りませんでした。',
  '简介与正文都不能为空': '概要と本文はどちらも空にできません',
  '简介：什么时候该用这个技能': '概要：このスキルをいつ使うか',
  '管理知识库': 'ナレッジベースを管理',
  '粘贴规则 JSON': 'ルール JSON を貼り付け',
