  '系统配音失败：{0}': '端末の音声に失敗：{0}',
  '系统配音超时了（这台设备的语音引擎没有回应）。再试一次，或改用 MiMo。': '端末の音声がタイムアウトしました（音声エンジンが応答しません）。再試行するか MiMo に切り替えてください。',
  '系统配音（零配置）': '端末の音声（設定不要）',
  '系统里没有任何语音识别服务，App 无论怎么写都用不了语音 —— 需要去应用商店装一个（例如各家的语音助手），或改用文字输入。': 'このシステムには音声認識サービスが無いため、アプリをどう作っても音声入力は使えません。アプリストアから導入するか（各社の音声アシスタントなど）、文字入力に切り替えてください。',
