  '网络不通：请检查手机网络/代理，然后重试。': 'ネットワークに接続できません。スマホのネットワーク/プロキシを確認して再試行してください。',
  '置顶': '先頭に固定',
  '美化是**本机 ffmpeg 滤镜**做的（调色 / 锐化 / 磨皮 / 暗角）：不联网、不花额度、秒级完成。': '補正は**端末内の ffmpeg フィルター**で行います（色調整 / シャープ / 肌補正 / 周辺減光）。通信なし・枠を消費せず・数秒で完了。',
  '美团 LongCat。适合已经拿到 LongCat Key 的用户。': '美団 LongCat。すでに LongCat Key を持っている方向け。',
