  '联网请求': 'オンラインリクエスト',
  '聚合平台，模型名照它站内的写': 'アグリゲータープラットフォームです。モデル名はサイト内の表記どおりに書いてください',
  '聚合端点：一个 Key 就能用到 DeepSeek / MiMo / LongCat / GLM / Qwen / Claude / GPT 等多家模型。适合不想挨家注册、只想填一次 Key 的人。': '集約エンドポイント：1つの Key で DeepSeek / MiMo / LongCat / GLM / Qwen / Claude / GPT など複数社のモデルが使えます。各社に登録せず、Key を1回だけ入力したい人向け。',
  '能不能放取决于手机上的 WebView 解码器；放不出来时会在这里说明，并可以改用其它应用打开。': '再生できるかは端末の WebView のコーデック次第です。再生できない場合はここに表示し、別のアプリで開けます。',
  '脚本原话（出问题时能看出来卡在哪）': 'スクリプトの生ログ（問題時にどこで止まったか分かります）',
  '自定义': 'カスタム',
  '自定义厂家才需要你填地址；内置厂家的地址一律自动用内置值。': 'アドレスの入力が必要なのはカスタム提供元だけです。内蔵の提供元は常に内蔵の値が自動で使われます。',
  '自定义端点': 'カスタムエンドポイント',
  '自定义配色还没做。现在有「浅色 / 深色 / 像素」三套皮肤，点「自定义」不会切主题 —— 也不会把主题切到一个不存在的状态。': 'カスタム配色は未実装です。実際に使えるスキンは「ライト／ダーク／ピクセル」の3つで、「カスタム」を押してもテーマは切り替わりません —— 存在しない状態にテーマを置き去りにもしません。',
  '自己手写一条': '自分で 1 件書く',
  '自检本身出错了：{0}': 'セルフチェック自体が失敗しました：{0}',
  '自检结果已写进运行日志并生成报告 —— 在分享面板里选一个应用发给开发者即可（报告里没有 Key）。': 'セルフチェック結果は実行ログに記録し、レポートを生成しました — 共有シートでアプリを選んで開発者に送ってください（レポートに Key は含まれません）。',
  '至少要放 1 个成员 —— 池子里一个模型都没有的话，选中它必然失败。': 'メンバーを最低1つ入れてください —— モデルが1つもないプールを選ぶと必ず失敗します。',
  '至少要有一个 model id：手填一个，或用「获取模型」勾一个。': 'model id が最低1つ必要です：手入力するか、「モデルを取得」で選んでください。',
  '船体刚刚被撞过，主电源断了，副氧还剩 40 分钟，通讯断续（一次只能说几句）。舱里只有一名船员还醒着。': '船体は先ほど衝突され、主電源は落ち、予備酸素は残り40分、通信は途切れがち（一度に数文だけ）。船内で起きている乗員は一人だけ。',
  '芯片': 'チップ',
  '芯片：{0}': 'チップ：{0}',
  '苏打': '苏打',
  '英文女声 · 活泼': '英語女性 · 活発',
  '英文女声 · 甜美': '英語女性 · 甘い',
  '英文男声 · 沉稳': '英語男性 · 落ち着き',
  '英文男声 · 阳光': '英語男性 · 爽やか',
  '茉莉': '茉莉',
  '获取中…': '取得中…',
  '获取模型': 'モデルを取得',
  '获取模型列表需要 API Key：先在上面填好 Key 再点「获取模型」。（实测这四家的 /models 都要鉴权，不带 Key 一律 401。）': 'モデル一覧の取得には API Key が必要です：先に上の Key を入力してから「モデルを取得」を押してください。（実測：この4社の /models はすべて認証が必要で、Key なしは必ず 401 です。）',
  '获取模型列表需要 API Key：自定义端点绝大多数也要鉴权。': 'モデル一覧の取得には APIキー が必要です：カスタムエンドポイントもほとんどが認証を要求します。',
  '获取模型列表需要 API Key：请先填写 {0} 的 Key 再点获取。（实测这四家的 /models 都要求鉴权，不带 Key 一律返回 401。）': 'モデル一覧の取得には APIキー が必要です：先に {0} の Key を入力してから取得を押してください。（実測ではこの4社の /models はすべて認証必須で、Key なしは一律 401 です。）',
  '落盘日志文件：{0}': 'ディスクに保存するログファイル：{0}',
  '虚拟屏': '仮想ディスプレイ',
  '虚拟屏已创建': '仮想ディスプレイ作成済み',
  '虚拟屏是「看不见」的：目标 App 在里面跑，物理屏上什么都不显示。': '仮想ディスプレイは「見えない」画面です。対象アプリはその中で動き、実画面には何も表示されません。',
  '表格整理': '表の整理',
  '被上游拒绝（403：地区封锁）': '上流に拒否（403：地域ブロック）',
  '被上游拒绝（403：当成非官方客户端）': '上流に拒否（403：非公式クライアント扱い）',
  '被限流了：等一会儿再试，或换一个模型。': 'レート制限です：少し待って再試行するか、別のモデルに切り替えてください。',
  '被限流（429）': 'レート制限（429）',
  '装不动也不要紧：这个模型包里 172 MB 的规则文件**不会解出来**（实测对我们没用），所以只占约 32 MB。也可以手动装 —— 把这几个文件放进下面这个目录：\n{0}': 'ダウンロードできなくても大丈夫です：アーカイブ内の 172 MB のルールファイルは**展開しません**（実測で不要）。そのため約 32 MB しか使いません。手動でも入れられます —— 次のディレクトリに必要ファイルを置いてください：\n{0}',
  '装入样例': 'サンプルを入れる',
  '装好了': '導入完了',
  '装好了：本机离线配音现在可以用了（离线、零 Key）。': '導入完了：端末内吹き替えが使えます（オフライン・Key 不要）。',
  '要修的图': '編集する写真',
  '要执行什么不能为空 —— 到点它会作为一条消息发给模型。': '実行内容は空にできません —— 時刻になるとメッセージとしてモデルに送信されます。',
  '要执行什么（会作为一条消息发给模型）': '実行内容（メッセージとしてモデルに送信されます）',
  '要执行的内容：': '実行する内容：',
  '要点 + 时间线，别再让我读完': '要点＋年表。全部読まなくていい',
  '要用就回「设置 → 模型」填上它的 API Key。': '使うには「設定 → モデル」に戻って、その API Key を入れてください。',
  '要用就回「设置 → 模型」把 Zen 那条打开（它经 App 内代理转发）。': '使うには「設定 → モデル」に戻って Zen の項目をオンにしてください（アプリ内の代理経由で転送します）。',
  '要用就回「设置 → 模型」把「免费模型（无需 Key）」打开。': '使うには「設定 → モデル」に戻って「無料モデル（Key 不要）」をオンにしてください。',
  '规则：① 只以你的角色身份说话，**不要出戏**、不要解释自己是 AI、不要总结或复述我的问题；② 每次回复短一点（2-3 句），把行动的余地留给我；③ **不要替我决定**、不要替我写台词；④ 我说「结束」时，给出这个角色的结局（一两句，说清发生了什么）。': 'ルール：① あなたのキャラクターとしてだけ話す —— **役を降りない**、自分が AI だと説明しない、私の質問を要約・復唱しない；② 返答は短く（2〜3文）、行動の余地を私に残す；③ **私の代わりに決めない**、私の台詞を書かない；④ 私が「終わり」と言ったら、このキャラクターの結末を出す（何が起きたかを1〜2文で）。',
  '视觉编码器（mmproj）': '視覚エンコーダ（mmproj）',
  '视频': '動画',
  '视频已生成：{0}': '動画を生成しました：{0}',
  '视频是异步任务：几十秒到几分钟都正常，期间不会重复提交。': '動画は非同期タスクです：数十秒〜数分かかるのは正常で、その間は再送信しません。',
  '视频模型': '動画モデル',
  '视频请求的形状同样按各家文档写：豆包 Seedance（方舟异步任务）/ MiniMax / 通义万相（百炼异步）/ 硅基流动 各一套 —— **能不能通要试**；失败会把上游原话显示出来。': '動画リクエストの形式も各社のドキュメントどおりです：豆包 Seedance（Ark 非同期タスク）/ MiniMax / 通義万相（百錬の非同期）/ SiliconFlow がそれぞれ別形式 —— **通るかどうかは試すしかありません**。失敗時は上流の文言をそのまま表示します。',
  '角色三视图专家': 'キャラ三面図の専門家',
  '角色现在是**打字**的：本机还没有「朗读回复」（语音合成在「创作台 → 口播/短剧」那条线上，不在会话里）——想让角色出声要另做一层，已列入后续。': '今のところキャラクターは**文字**です：本機にはまだ「読み上げ返答」がありません（音声合成は「スタジオ → ナレーション/ショートドラマ」のライン上にあり、会話の中にはありません）——キャラクターに声を与えるにはもう一層必要で、今後に予定しています。',
  '角色的**记忆只在这一局里**：开个新会话它就忘了。想让某件事长期记住，写进设置里的「记忆」。': 'キャラクターの**記憶はこの局の中だけ**：新しいセッションを開けば忘れます。ある事を長期で覚えさせたいなら、設定の「記憶」に書いてください。',
  '解出来的模型文件不齐，缺：{0}（压缩包已保留在 {1}，可以重试）': '展開後のモデルファイルが不足しています：{0}（アーカイブは {1} に残してあるので再試行できます）',
  '解包失败（退出码 {0}）：{1}': '展開に失敗（終了コード {0}）：{1}',
  '解压完成但仍找不到运行时文件': '解凍は完了しましたが、ランタイムファイルが見つかりません',
  '解除配对': 'ペアリングを解除',
  '订阅失败：{0}': '購読に失敗しました：{0}',
  '认不出的厂家按 OpenAI 兼容形状试：size 用像素值。': '判別できないベンダーは OpenAI 互換の形式で試します：`size` はピクセル値です。',
  '让 App 能安装 APK（例如以后把新版本安装包交给它来升级）。每次安装系统还会再问你一次。': 'アプリが APK をインストールできるようにします（例：新しいビルドを渡して更新する）。インストールのたびにシステムが再度確認します。',
  '让 App 能读写手机里任意目录的文件（不只是自己那一份）。不开也能用：会话与工具会在自己的私有目录、以及你手动选给它的范围内活动。': 'アプリが端末内の任意のフォルダのファイルを読み書きできるようにします（自分の領域だけではありません）。オフでも動きます：その場合、セッションとツールはアプリ専用フォルダと、あなたがファイル選択で渡した範囲だけで動きます。',
  '让 DSH 写一份文档或生成一张图，产物会出现在这里。': 'DSH にドキュメントを書かせるか画像を生成させると、成果物がここに表示されます。',
  '让「短剧剧本专家」写一版': '「ショートドラマ脚本家」に書かせる',
  '让会话能用子智能体': '子エージェント',
  '让会话能联网搜索': 'セッションでウェブ検索を有効にする',
  '让模型**演一个角色**，你跟他打交道 —— 每张牌都写清了「谁演谁、在哪、你要办成什么、什么时候算完」。**这不是聊天**：聊天没有压力、没有后果、也没法结束。': 'モデルに**ある役を演じさせ**、あなたがその相手をする —— どのカードにも「誰が誰を演じるか、どこで、何を成し遂げるか、いつ終わるか」が書かれています。**これはチャットではありません**：チャットには圧力も結果も、終わる方法もありません。',
  '让模型**长期记住**你的事（身份、偏好、项目事实、禁忌）：可以自己写，也可以从最近的会话里**自动提炼**候选、由你确认。它写进 AGENTS.md，DSH 在**每个新会话的第一个请求前**注入模型上下文；**对已经打开的会话不生效**，要新建会话。': 'モデルに**長期的に覚えてほしいこと**（立場・好み・プロジェクトの事実・禁忌）を書けます。自分で書くことも、最近のセッションから候補を**自動抽出**して確認することもできます。AGENTS.md に書き込まれ、DSH が**新しいセッションの最初のリクエスト前**にモデルのコンテキストへ注入します。**すでに開いているセッションには効きません** —— 新しいセッションを作ってください。',
  '让模型演一个角色，你跟他打交道 —— 每局都有目标和结束条件': 'モデルに役を演じさせ、あなたがその相手をする —— どの局にも目標と終了条件があります',
  '让模型记住这些（关闭后不再注入）': 'モデルにこれらを覚えさせる（オフにすると注入しなくなります）',
  '让模型读一段真实对话，提炼出长期有效的偏好与事实。**提炼结果不会自动写入**，要你勾选确认；每次提炼都会真实调用一次模型（会花额度）。': 'モデルに実際の会話を読ませ、長期的に有効な好みや事実を抽出させます。**抽出結果は自動では書き込まれません** —— 残すものをチェックしてください。抽出のたびに実際にモデルを 1 回呼び出します（枠を消費します）。',
  '让谁帮你写？': '誰に書かせますか？',
  '记得先在「云端大模型」里把「{0}」这家配好（厂家 id 用 {1}）—— Key 是从那边读的。': '先に「クラウド大規模モデル」で「{0}」を設定してください（プロバイダ id は {1}）—— Key はそこから読み取ります。',
  '记忆': '記憶',
  '记忆占用 {0} / {1} 字节': '記憶の使用量 {0} / {1} バイト',
  '记忆总量超了：现在约 {0} 字节，上限 {1} 字节。请先删掉几条再添加（总预算与专家说明共享 DSH 的 64 KB 注入上限）。': '記憶の合計が上限を超えました：現在およそ {0} バイト、上限 {1} バイト。先にいくつか削除してください（合計予算は専門家の説明と DSH の 64 KB 注入上限を共有します）。',
  '许可未知（请自行确认来源）': 'ライセンス不明（出所をご自身で確認ください）',
  '许可：{0}': 'ライセンス：{0}',
  '设为默认': 'デフォルトに設定',
  '设备凭据已失效，请重新配对': 'デバイス認証情報が無効になりました。もう一度ペアリングしてください',
  '设置': '設定',
  '设置 → 应用 → 特殊应用权限 → 使用情况访问权限（部分手机叫「有权查看使用情况的应用」）': '設定 → アプリ → 特別なアクセス権 → 使用状況へのアクセス（「使用状況にアクセスできるアプリ」という端末も）',
  '设置 → 应用 → 特殊应用权限 → 修改系统设置': '設定 → アプリ → 特別なアクセス権 → システム設定の変更',
  '设置 → 应用 → 特殊应用权限 → 安装未知应用 → 本应用 → 允许': '設定 → アプリ → 特別なアクセス権 → 不明なアプリのインストール → 本アプリ → 許可',
  '设置 → 应用 → 特殊应用权限 → 所有文件访问权限（Android 11 及以上；部分手机在「应用管理 → 本应用 → 权限 → 文件和媒体」里）': '設定 → アプリ → 特別なアクセス権 → すべてのファイルへのアクセス（Android 11 以降。一部の端末では「アプリ → 本アプリ → 権限 → ファイルとメディア」）',
  '设置 → 应用 → 特殊应用权限 → 显示在其他应用上层': '設定 → アプリ → 特別なアクセス権 → 他のアプリの上に重ねて表示',
  '设置：下载模型 / 启动服务 / 后端 / 知识库 / 联网': '設定：モデルのダウンロード / サービスの起動 / バックエンド / ナレッジベース / ウェブ検索',
  '访问敏感凭据': '機密認証情報へのアクセス',
  '证书 SHA-256 指纹': '証明書の SHA-256 フィンガープリント',
  '试听失败：{0}': '試聴に失敗：{0}',
  '试听这一句': 'この文を試聴',
  '该给的都给了': '必要なものはすべて揃いました',
  '语言': '言語',
  '语速': '速度',
  '语速中等，节奏稳定。': '中程度の速さ、安定したリズム。',
  '语速放慢一些，吐字清楚，停顿从容。': 'ややゆっくり、はっきりと、余裕のある間で。',
  '语速是发给 MiniMax 的倍率（1.00× 为原速）。音色列表拉不到也不影响用：默认音色照样能配。': '速度は MiniMax に送る倍率です（1.00× が元の速さ）。音色一覧が取得できなくても使えます：デフォルト音色でそのまま合成できます。',
  '语速稍快一些，节奏紧凑但不含糊。': 'やや速め、テンポよく、ただし曖昧にしない。',
  '语音识别不可用': '音声認識を利用できません',
  '语音识别失败：{0}': '音声認識に失敗しました：{0}',
  '语音输入': '音声入力',
  '语音输入用不了：这台手机的系统里**没有**任何语音识别服务（可处理识别的应用数={0}）。装一个语音助手类应用后它才会生效；在此之前请用文字输入。': '音声入力は使えません：この端末には音声認識サービスが**ありません**（認識を扱えるアプリ数={0}）。音声アシスタント系のアプリを入れると有効になります。それまでは文字入力をお使いください。',
  '说明：DSH 的运行方式由 overlay 决定 —— 它把模型路由指向你填的端点。这也是为什么换端点必须重新保存一次。': '説明：DSH の動作方法は overlay が決めます — モデルのルーティングをあなたが入力したエンドポイントへ向けます。だからエンドポイントを変えたら必ずもう一度保存が必要です。',
  '说明：装进来之后，在下面点「建索引」，这一包才会被检索。建好索引的包，在「本地对话」里提问时会**自动查** —— 把最相关的几段资料（每包最多 2 段、总共最多 3 段）一起发给模型。⚠️ 查到不等于模型一定照它回答；资料没命中时，一句都不会发出去。': '説明：取り込んだあと、下の「索引を作成」を押すとそのパックが検索対象になります。索引を作ったパックは「ローカル対話」で質問すると**自動で検索**され、最も関連する数段（1パックにつき最大2段、合計最大3段）が質問と一緒にモデルへ送られます。⚠️ 見つかったからといってモデルがそれに従うとは限りません。1件も一致しなければ、何も送られません。',
  '说话人：{0}（共 {1} 个，试听一下挑一个）': '話者：{0}（全 {1} 個・試聴して選んでください）',
  '请先填 API Key 再点「测试并保存」—— 安全区里也还没有这一家的 Key。这一家的模型列表与对话都要求鉴权，不带 Key 一律 401。': '「テストして保存」の前に API Key を入力してください — セキュア領域にもこのサービスの Key はありません。このサービスはモデル一覧もチャットも認証が必要で、Key なしは必ず 401 です。',
  '请填**另一个账号**的 Key —— 同一账号多建几把共享同一份配额，加了也没用。': '**別アカウント**の Key を入力してください —— 同一アカウントで複数作っても同じ割り当てを共有するので、追加しても効果はありません。',
  '请帮忙推广一下我的公众号，粉丝太少没有更新动力了': '私の公式アカウントを宣伝してください。フォロワーが少なすぎて更新する気になれません。',
  '请求 {0} 超时': '{0} へのリクエストがタイムアウトしました',
  '请求太频繁或已达额度上限，请稍后重试。': 'リクエストが多すぎるか、上限に達しています。しばらくしてから再試行してください。',
  '请求太频繁，被限流了。等几秒到一分钟再试。': 'リクエストが多すぎて制限されました。数秒〜1分待ってから試してください。',
  '请求失败：{0}': 'リクエスト失敗：{0}',
  '请求被拒绝（多为模型名写错或参数不被支持）。': 'リクエストが拒否されました（多くはモデル名の誤りか、未対応のパラメータです）。',
  '请求被拒绝，请检查模型名、Base URL 与 Key。': 'リクエストが拒否されました。モデル名、Base URL、Key を確認してください。',
  '请求超时：网络太慢或服务商无响应。检查网络后重试。': 'リクエストがタイムアウトしました：ネットワークが遅いか、提供元が応答していません。ネットワークを確認して再試行してください。',
  '请选择记忆的 JSON 文件（.json）。': '記憶の JSON ファイル（.json）を選んでください。',
  '请阅读这个文件：{0}': 'このファイルを読んでください：{0}',
  '读不出这张图的尺寸，去水印用不了（怕把框盖错地方）—— 可以只做美化。': 'この画像のサイズが読めないため、透かし消しは使えません（枠を当てずっぽうにはしません）。補正だけなら使えます。',
  '读不到会话历史': 'セッションの履歴を読み込めませんでした',
  '读不到当前应用的签名，没法确认新包是不是同一家签的；出于安全，这次不装。': '現在のアプリの署名を読み取れず、新しいパッケージが同じ発行元の署名かを確認できません。安全のため今回はインストールしません。',
  '读不到本机内存，先按保守估计': '本機のメモリを取得できないため、控えめに見積もります。',
  '读取 {0}/schedules.json 失败：{1}': '{0}/schedules.json の読み込みに失敗しました：{1}',
  '读取会话列表失败：{0}': 'セッション一覧を読み込めませんでした：{0}',
  '读取失败': '読み込みに失敗しました',
  '读取安装包签名时出错了。': 'インストールパッケージの署名を読み取る際にエラーが発生しました。',
  '读取已保存的设置失败（{0}）。下面显示的是空表单，**不代表你没配过** —— 请先不要重填，把这条报给开发者。': '保存済みの設定を読み込めませんでした（{0}）。下のフォームは空ですが、**設定していないという意味ではありません**。まず再入力せず、この内容を開発者に報告してください。',
  '读取开关状态失败：{0}': 'スイッチの状態を取得できませんでした：{0}',
  '读取文件': 'ファイルを読み込む',
  '读取文件失败：{0}': 'ファイルを読み込めませんでした：{0}',
  '读取权限失败：{0}': '権限の取得に失敗しました：{0}',
  '调色、锐化、擦除水印（本机处理，不联网）': '色調整・シャープ・透かし消し（端末内処理・通信なし）',
  '豆包 Seedance 的分辨率由模型与比例决定，这里不能选。': '豆包 Seedance の解像度はモデルと比率で決まるため、ここでは選べません。',
  '账户余额不足，请先充值。': 'アカウント残高が不足しています。先にチャージしてください。',
  '资料库': 'ライブラリ',
  '超时': 'タイムアウト',
  '超时（{0}s 没响应）': 'タイムアウト（{0} 秒応答なし）',
  '跟它聊两句（简单对话）': '少し話してみる（簡単な会話）',
  '跟本机模型说点什么…': 'ローカルモデルに話しかけてください…',
  '跟本机模型说点什么（也可以发图）…': 'ローカルモデルに話しかけてください（画像も付けられます）…',
  '跟随当前会话（推荐）': '現在のセッションに追従（推奨）',
  '路径是 /openai/v1（不是 /v1），漏掉 openai 会 404。': 'パスは /openai/v1 です（/v1 ではありません）。openai を省くと 404 になります。',
  '跳过 {0} 个噪音目录': 'ノイズディレクトリを {0} 個スキップ',
  '跳过这个版本': 'このバージョンをスキップ',
  '身份': '立場',
  '轮换池': 'ローテーションプール',
  '轮换池 = 把几个模型排成一队：前一个被限流（429）或不可用时，自动换下一个，直到有一个能答。池子本身不存 Key，用的是各厂家各自的 Key。': 'ローテーションプールは複数のモデルを一列に並べます：先頭が制限（429）や利用不可になると、答えられるモデルが見つかるまで自動で次を試します。プール自体は Key を保存せず、各サービスの Key を使います。',
  '轮换池 {0} · 本次用 {1}': 'ローテーション {0} · 今回は {1} を使用',
  '轮换池 {0}，{1} 个模型，{2}': 'ローテーションプール {0}、{1} モデル、{2}',
  '轮换池 · {0} 个成员：{1}': 'ローテーションプール · {0} メンバー：{1}',
  '轮换池「{0}」已保存：{1} 个成员按顺序依次尝试': 'ローテーションプール「{0}」を保存しました：{1} メンバーを順番に試します。',
  '轮换池已保存': 'ローテーションプールを保存しました',
  '轮换组 · {0} 个模型': 'ローテーショングループ · {0} モデル',
  '轮换组：': 'ローテーショングループ：',
  '载入应用列表': 'アプリ一覧を読み込む',
  '输入': '入力',
  '输入文字': '文字を入力',
  '输入消息…': 'メッセージを入力…',
  '边界（如实说）': 'できること・できないこと',
  '运行中 · {0} · 127.0.0.1:{1}': '稼働中 · {0} · 127.0.0.1:{1}',
  '运行中 · 端口 {0} · {1}': '実行中 · ポート {0} · {1}',
  '运行内存': 'メモリ',
  '运行历史': '実行履歴',
  '运行时清单不是合法 JSON。': '実行環境のマニフェストが有効な JSON ではありません。',
  '运行时清单是空的。': '実行環境のマニフェストが空です。',
  '运行时清单的格式不对：它应该是一个 JSON 对象。': '実行環境のマニフェストの形式が正しくありません。JSON オブジェクトである必要があります。',
  '运行时清单缺少 {0} 字段。': '実行環境のマニフェストに {0} フィールドがありません。',
  '运行时目录': 'ランタイムディレクトリ',
  '运行环境**随这个安装包自带**（约 32 MB）—— **不需要联网**，直接在本机解开（约 26000 个文件）。这一步只做一次，以后更新不用再下。': '実行環境は**このインストーラに同梱**されています（約 32 MB）—— **ネット不要**で、端末内で展開します（約 26,000 ファイル）。これ一回だけで、以後の更新では不要です。',
  '运行环境（约 32 MB）不在这个安装包里 —— 那样每次更新都要重下它。改成**第一次打开时下这一次**，支持断点续传；下完在本机解开（约 26000 个文件）。这一步只做一次，以后更新不用再下。': '実行環境（約 32 MB）はこのインストーラには入っていません —— そうしないと更新のたびに再ダウンロードになるためです。代わりに**初回起動時に一度だけ**ダウンロードし（レジューム対応）、端末内で展開します（約 26,000 ファイル）。これ一回だけで、以後の更新では不要です。',
  '运行记录': '実行記録',
  '运行记录（对照 game-qa 的验收口径逐项确认）': '実行記録（game-qa の受け入れ基準に沿って項目ごとに確認）',
  '运行：{0}': '実行：{0}',
  '返回': '戻る',
  '返回内容过大（不像一份版本清单）': '返ってきた内容が大きすぎます（バージョン情報としては不自然）',
  '还不在任何池子里': 'まだどのプールにも入っていません',
  '还差一步：系统里要允许本应用「安装未知应用」。点下面的按钮去打开，回来再点「安装」。': 'あと 1 歩：システムでこのアプリに「提供元不明のアプリ」のインストールを許可する必要があります。下のボタンで設定を開き、戻ってから「インストール」を押してください。',
  '还差模型。最快的一条路：去「设置 → 模型」打开「免费模型（无需 Key）」——不用填任何 Key，打开就能用；想用自己的模型，再填地址和 API Key。': 'モデルがありません。一番早いのは「設定 → モデル」で「無料モデル（Key 不要）」をオンにすることです — Key は不要で、そのまま使えます。自分のモデルを使うなら、アドレスと API Key を入力してください。',
  '还没允许：{0}': 'まだ許可されていません：{0}',
  '还没建索引 —— 不建就只能看，没法被检索。': '索引が未作成です。作らないと閲覧だけで検索はできません。',
  '还没开始对话，正在按新模型准备会话…': 'まだ会話を始めていません。新しいモデルでセッションを準備しています…',
  '还没放成员 —— 从下面「所有已注册的模型」里点几个。': 'メンバーがまだいません —— 下の「登録済みのモデル」からいくつか選んでください。',
  '还没有': 'まだありません',
  '还没有 Key？到 {0} 免费注册 → 控制台「API Keys」创建密钥（sk- 开头）→ 粘贴到这里。': 'APIキーがまだない？{0} で無料登録 → コンソールの「API Keys」でキー（sk- で始まる）を作成 → ここに貼り付け。',
  '还没有产物': '成果物はまだありません',
  '还没有任何模型 —— 先去「设置 → 模型」加一个。': 'モデルがまだありません —— 先に「設定 → モデル」で追加してください。',
  '还没有任何记忆。上面写一条，新建会话后模型就会看到它。也可以往下翻，从最近一次会话里提炼。': 'まだ記憶がありません。上に 1 件書けば、新しいセッションでモデルがそれを見ます。下へスクロールして、最近のセッションから抽出することもできます。',
  '还没有作品': '作品はまだありません',
  '还没有别的会话': 'まだ他のセッションはありません',
  '还没有可恢复的会话。\n点右下角新建一个。': '復元できるセッションがありません。\n右下をタップして新規作成してください。',
  '还没有可用模型 · 去设置': '利用可能なモデルがありません · 設定へ',
  '还没有可用模型。': '利用可能なモデルがまだありません。',
  '还没有可用模型。想马上就用：去「设置 → 模型」打开「免费模型（无需 Key）」，不用填 Key 也不花钱；想用自己的模型（DeepSeek / Agnes 等），再填地址和 API Key 点「测试并保存」。': '使えるモデルがまだありません。すぐ使うなら：「設定 → モデル」で「無料モデル（Key 不要）」をオンに — Key も費用も不要です。自分のモデル（DeepSeek / Agnes など）を使うなら、アドレスと API Key を入力して「テストして保存」を押します。',
  '还没有可用模型，去设置': '利用可能なモデルがありません。設定へ',
  '还没有可用的云端模型：请先在「设置 → 模型」里配好一个（填 Key 并保存）。': '利用可能なクラウドモデルがありません：「設定 → モデル」で1つ設定してください（Key を入力して保存）。',
  '还没有可用的模型': '利用可能なモデルがありません',
  '还没有开启任何专家': '有効なエキスパートはまだありません',
  '还没有开启任何专家；开启后会在会话的「专家中心」里出现': '有効なエキスパートはまだありません。有効にするとセッションの「エキスパートセンター」に表示されます',
  '还没有执行记录。': '実行履歴はまだありません。',
  '还没有装任何知识库：可以下载下面列出的，或从手机导入。': 'ナレッジベースはまだありません。下からダウンロードするか、スマホから取り込んでください。',
  '还没有装知识库。知识库是给本地模型查的离线资料：不联网、不花额度。': 'ナレッジベースはまだありません。ローカルモデルが調べるオフライン資料で、通信も課金も不要です。',
  '还没有规则。去「后台操作台」点「开始录制」，录一条吧。': 'まだルールがありません。「バックグラウンド操作台」の「録画開始」で録ってください。',
  '还没有轮换池。': 'ローテーションプールがまだありません。',
  '还没有配置模型': 'モデルが未設定です',
  '还没测过': '未計測',
  '还没给日历权限：授权后任务才会写进系统日历（系统会弹窗问你）。': 'カレンダーの権限がまだ許可されていません：許可するとタスクがシステムカレンダーに書き込まれます（システムが確認のダイアログを出します）。',
  '还没装模型：要下 **31.5 MB**（装好后占约 32 MB），下完自动解包。': 'モデル未導入：**31.5 MB** をダウンロードします（導入後は約 32 MB）。完了後に自動で展開します。',
  '还没选图。可以从相册选，也可以直接用「作品」里已经生成的那张。': 'まだ写真を選んでいません。アルバムから選ぶか、「作品」にある生成済みの画像をそのまま使えます。',
  '还没选文件。点下面「从资料库选」—— 只列工作区里的视频。': 'まだファイルを選んでいません。下の「ライブラリから選ぶ」を押してください —— ワークスペース内の動画だけが並びます。',
  '还没配 Key —— 没凭据这条模型必然失败': 'Key 未設定 —— 認証情報がないとこのモデルは必ず失敗します',
  '这 5 项不是普通权限：Android 不允许应用自己开，也没有「应用内开关」—— 只能在系统的「特殊应用权限」页里拨。下面写清每一项是干嘛的。': 'この 5 つは通常の権限ではありません：Android はアプリ自身による付与を許さず、アプリ内スイッチもありません —— システムの「特別なアクセス権」ページで切り替えるしかありません。以下に各項目の用途を書きます。',
  '这一条**没有配音**': 'このカットには**吹き替えがありません**',
  '这一条太长了（上限 {0} 字节，约 600 多个汉字）': 'この項目は長すぎます（上限 {0} バイト、漢字約 600 字強）',
  '这一项已经不在配置里了，请重新选择。': 'この項目は設定に存在しません。もう一度選び直してください。',
  '这七个技能来自 NovelToGame v0.4.0（MIT 许可），只改写了简介并加了署名，正文与参考文件保持原样。': 'この7つのスキルは NovelToGame v0.4.0（MIT ライセンス）から来ています。書き換えたのは紹介文だけで、出典表記を追加し、本文と参照ファイルはそのままです。',
  '这三个就是设置里那几个模型（文本模型 = 首页新会话用的那个；图形/视频 = 「设置 → 图像 / 视频模型」），在这儿改等于在设置里改 —— 创作台生成时会**直接用**这里选的。': 'この三つは設定にあるものと同じです（テキストモデル＝新しい会話で使うもの、画像/動画＝「設定 → 画像 / 動画モデル」）。ここで変えるのは設定で変えるのと同じで、スタジオの生成はここで選んだものを使います。',
  '这不像一个完整网址：要以 http:// 或 https:// 开头。': '完全な URL ではないようです。http:// または https:// で始めてください。',
  '这两颗按钮跟手机档次无关 —— 同一份模型，只是换「谁来算」：CPU 是通用的，慢一点但稳；GPU 用图形芯片加速，通常快好几倍，但**部分机型在长对话时会把引擎干崩**（真机上遇到过，崩了就会报连不上）。所以默认给了 CPU；想快就切 GPU 试 —— 万一崩，下次启动会自动换回 CPU。': 'この 2 つのボタンはスマホのグレードとは関係ありません。同じモデルで「誰が計算するか」を選ぶだけです。CPU は汎用で少し遅いが安定、GPU はグラフィックスチップで計算し通常は数倍速いものの、**一部の機種では長い会話でエンジンが落ちます**（実機で発生。落ちると接続エラーになります）。そのため既定は CPU です。速さが欲しければ GPU に切り替えて試してください —— 万一落ちても、次回起動時は自動で CPU に戻ります。',
  '这个 Android 版本不需要': 'この Android バージョンでは不要です',
  '这个包与当前应用的**签名不一致**，不能覆盖安装 —— 它可能不是同一个来源发的。如果你确实换了签名钥匙，唯一的办法是卸载重装（数据会丢）。': 'このパッケージは**署名が現在のアプリと一致しない**ため、上書きインストールできません —— 同じ発行元ではない可能性があります。実際に署名鍵を変更した場合は、アンインストールして入れ直すしかありません（データは失われます）。',
  '这个包大得不像话（超过 {0}），已经停下不下了。': 'このパッケージは大きすぎます（{0} 超）。ダウンロードを中止しました。',
  '这个名字只是本 App 的显示名 —— ACP 协议没有改名功能，DSH 那边这条会话不受影响。留空保存 = 恢复成默认显示。': 'この名前は本アプリの表示名だけです — ACP プロトコルに改名機能はなく、DSH 側のこのセッションには影響しません。空で保存すると既定の表示名に戻ります。',
  '这个安装包里没有签名 —— 正规发布的包一定有签名，所以不装它。': 'このインストールパッケージには署名がありません —— 正規に配布されたパッケージには必ず署名があるので、インストールしません。',
  '这个文件 App 内放不出来': 'このファイルはアプリ内では再生できません',
  '这个文件不是一个能识别的安装包。': 'このファイルは認識できるインストールパッケージではありません。',
  '这个文件夹在 App 私有目录里，其它应用读不到；「分享」或「复制路径」都能把它交出去。': 'このフォルダはアプリのプライベートディレクトリ内にあり、他のアプリからは読めません。「共有」か「パスをコピー」で渡せます。',
  '这个文件看起来是二进制': 'このファイルはバイナリのようです',
  '这个格式 App 内不能预览': 'この形式はアプリ内でプレビューできません',
  '这个模型在你所在地区不可用（不是 Key 的问题）。': 'このモデルはお住まいの地域では利用できません（Key の問題ではありません）。',
  '这个模型在清单里没有任何下载源': 'このモデルはマニフェストにダウンロード元がありません',
  '这个模型在该端点上不存在。请点「获取模型」重新选。': 'このモデルはそのエンドポイントに存在しません。「モデルを取得」をタップして選び直してください。',
  '这个模型文件只带 {0} 格缓存，上下文已收敛到 {0} 格（你设的是 {1}）—— 它的上下文上限就是那么多，装不下更长的对话': 'このモデルファイルはキャッシュが {0} スロットしかないため、コンテキストを {0} に絞りました（設定は {1}）—— これが上限で、それより長い会話は入りません。',
  '这个模型没有在 DSH 的路由里注册。\n下一步：回「设置 → 模型」把默认模型重新点一次（这会让 App 重写配置），或者到会话里用模型按钮重新选一次。': 'このモデルは DSH のルーティングに登録されていません。\n次の手順：「設定 → モデル」に戻ってデフォルトモデルをもう一度タップする（アプリが設定を書き直します）か、セッションでモデルボタンから選び直してください。',
  '这个模型没法在当前会话里直接切，正在重建会话…': 'このモデルは現在のセッションでは直接切り替えられません。セッションを再構築しています…',
  '这个模型的对话缓存装不下了：它的上下文上限是 {0} token，当前这段对话已经接近上限。请点右上角新开一个会话，或换一个上下文更大的模型。': 'このモデルの会話キャッシュが一杯です：コンテキスト上限は {0} トークンで、現在の会話はすでに上限付近です。右上から新しいセッションを始めるか、より大きなコンテキストのモデルに切り替えてください。',
  '这个池子一个成员都没有 —— 在模型面板里选中它会直接失败，建议放进一两个模型或删掉它。': 'このプールにはメンバーが一人もいません —— モデルパネルで選んでも必ず失敗します。モデルを1〜2個入れるか、削除してください。',
  '这个池子里的模型所在厂家都还没配 API Key —— 现在选中它，发言时必然失败。去「设置 → 模型 → 我的模型」给其中至少一家填 Key。': 'このプール内のモデルのサービスはどれも API Key が未設定です — 今選ぶと発言時に必ず失敗します。「設定 → モデル → マイモデル」で少なくとも1社に Key を入力してください。',
  '这个账号下没有可用的系统音色。': 'このアカウントには利用できるシステム音色がありません。',
  '这些是什么意思？': 'これらは何ですか？',
  '这些说明是随 App 版本一起发出来的文字记录（离线存在安装包里）；App 不会联网检查新版本，也不会提示你升级。': 'これらの説明はアプリのバージョンと一緒に配布される記録です（インストールパッケージ内にオフラインで保存）。アプリは新しいバージョンをオンラインで確認せず、アップグレードも促しません。',
  '这份日志是为了让开发者看出"运行中哪里出错了"。它会包含：': 'このログは開発者が「実行中にどこでエラーが出たか」を確認するためのものです。含まれる内容：',
  '这份是本地缓存的公告，还没有和远端对上时间': 'これはローカルにキャッシュされたお知らせで、まだリモートと時刻を突き合わせていません。',
  '这会删掉所有记忆条目，并从 AGENTS.md 里移除它们。不可恢复。': 'すべての記憶項目を削除し、AGENTS.md からも取り除きます。元に戻せません。',
  '这台手机没有可接收分享的应用（系统返回 {0}）。': 'このスマホには共有を受け取れるアプリがありません（システムから {0}）。',
  '这台手机没有可用的「保存文件」界面（系统返回 {0}）。': 'このスマホには「ファイルを保存」画面がありません（システムから {0}）。',
  '这台手机没有可用的「文字转语音」引擎（系统里一个都没装）。两条路：① 到「系统设置 → 语言与输入 → 文字转语音」装一个引擎并下载中文语音包；② 改用 MiMo 或 MiniMax 配音 —— 在「设置 → 云端大模型 → MiMo / MiniMax」里填一个 API Key 即可。': 'この端末には使える「音声合成」エンジンがありません（一つも入っていません）。二つの方法：①「システム設定 → 言語と入力 → テキスト読み上げ」でエンジンを入れ、中国語の音声データをダウンロードする；② MiMo か MiniMax の音声合成に切り替える ——「設定 → クラウドモデル → MiMo / MiniMax」で API Key を入れるだけです。',
  '这台手机没有语音引擎？改用 MiMo（需 Key）': 'この端末に音声エンジンがない？MiMo に切り替え（Key が必要）',
  '这台手机没装中文语音数据。请到「系统设置 → 语言与输入 → 文字转语音」里下载中文语音包；或者改用 MiMo 配音（需要 Key）。': '中国語の音声データが入っていません。「システム設定 → 言語と入力 → テキスト読み上げ」でダウンロードするか、MiMo の音声（Key が必要）に切り替えてください。',
  '这台手机（或这个 Android 版本）里没有「{0}」的设置页 —— 国产 ROM 常把入口改名、藏起来或整个删掉。手动找：{1}': 'この端末（またはこの Android バージョン）には「{0}」の設定ページがありません —— 中国系 ROM は入口の名前を変えたり隠したり削除したりします。手動で開く：{1}',
  '这台设备上找不到能处理安装的应用（一般是定制系统裁掉了安装器），装不了。': 'この端末にはインストールを処理できるアプリがありません（カスタム ROM ではインストーラーが削られていることがあります）。インストールできません。',
  '这台设备上没有可以提炼的会话。': 'この端末には抽出できるセッションがありません。',
  '这台设备上没有可用的语音识别服务': 'このデバイスでは利用できる音声認識サービスがありません',
  '这台设备没有可写的日历（很多裸机没有系统日历账号），所以同步不了 —— 任务仍然只在这个 App 里跑。': 'この端末には書き込み可能なカレンダーがありません（カレンダーアカウントのない端末は多くありません）ので同期できません。タスクはこのアプリの中だけで動きます。',
  '这台设备没有能打开网页的应用，请手动访问：{0}': 'このデバイスには Web ページを開けるアプリがありません。手動でアクセスしてください：{0}',
  '这台设备没有能接收分享的应用': 'このデバイスには共有を受け取れるアプリがありません',
  '这台设备的名字': 'このデバイスの名前',
  '这家在本 App 里没接图像：点上面的「换一个」选一家支持图像的厂家。': 'このベンダーの画像は本アプリでは未接続です：上の「変更」から画像に対応したベンダーを選んでください。',
  '这家在本 App 里没接视频：点上面的「换一个」选一家支持视频的厂家（Agnes / 豆包 Seedance / MiniMax / 通义万相 / 硅基流动）。': 'このベンダーの動画は本アプリでは未接続です：上の「変更」から動画に対応したベンダー（Agnes / 豆包 Seedance / MiniMax / 通義万相 / SiliconFlow）を選んでください。',
  '这家没有内置的注册地址 —— 去它的官网申请 Key 就行。': 'このプロバイダーには登録用の URL がありません —— 公式サイトで Key を取得してください。',
  '这家还没配 Key': 'このプロバイダーは APIキー未設定です',
  '这就是当前那把主 Key，不用再加一遍': 'それは現在のメイン Key です。もう一度追加する必要はありません',
  '这张图打不开（Flutter 解码失败）：{0}\n\n{1}': 'この画像を開けません（Flutter のデコードに失敗）：{0}\n\n{1}',
  '这张图读不到了（可能刚被删除或移动），换一张试试。': 'この画像はもう読めません（削除・移動された可能性があります）。別のものを試してください。',
  '这把 Key 已经在列表里了': 'その Key はすでに一覧にあります',
  '这是什么': 'これは何か',
  '这是按消息长度**估算**的（ACP 目前不把真实用量推给 App），只看趋势别看小数。\n换窗三步：① 生成交接笔记 → ② 发出去 → ③ 新建一个会话继续。': 'これはメッセージ長からの**推定値**です（ACP は現時点で実際の使用量をアプリに送りません）。小数ではなく傾向だけ見てください。\n新しいウィンドウへの3手順：① 引き継ぎメモを生成 → ② 送信 → ③ 新しいセッションを作って続ける。',
  '这条会话在磁盘上没有可回放的消息。': 'このセッションにはディスク上に再生できるメッセージがありません。',
  '这条会话没能恢复': 'このセッションを復元できませんでした',
  '这条会话的记录没读出来 —— 会话文件可能已经不在了。你可以换一条，或者自己手写一条。': 'このセッションの記録を読み込めませんでした —— セッションファイルがもう無い可能性があります。別のセッションを選ぶか、自分で 1 件書いてください。',
  '这条会话里没有可提炼的对话内容（没有用户或助手的消息）。': 'このセッションには抽出できる会話内容がありません（ユーザーまたはアシスタントのメッセージがありません）。',
  '这条回答顶到了长度上限、被截断了（不是答完）。可以再发一句「继续」，或者把问题拆小一点再问。': 'この回答は長さの上限に達して途中で切れました（最後まで答えたわけではありません）。「続けて」と送るか、質問を小分けにしてください。',
  '这条是好的。': 'これは正常です。',
  '这条模型的清单里没有 sha256，而清单要求必须校验哈希，已拒绝安装：{0}': 'このモデルのマニフェストに sha256 がありませんが、マニフェストはハッシュ検証を必須にしています。インストールを拒否しました：{0}',
  '这条没能发出去：会话没能建起来，可以再试一次。': 'このメッセージは送れませんでした。セッションを作成できませんでした。もう一度お試しください。',
  '这条没能回上来。可以再发一次；若反复如此，去「设置 → 运行日志」看细节。': 'この返信は得られませんでした。もう一度送ってみてください。繰り返す場合は「設定 → 実行ログ」で詳細を確認できます。',
  '这条通道现在是通的，不用填 Key。模型清单随时会变，以「获取模型」拉到的那份为准。': 'このチャネルは今つながっています（Key 不要）。モデル一覧は随時変わります。「モデルを取得」で取れたものを正としてください。',
  '这条通道用不了的时候才需要它：点一次自检，它会告诉你到底是哪种问题（网络不通 / 被上游拒绝 / 模型名退役 / Key 失效 / 限流），并可以把结论一键发给开发者。': 'このチャンネルが使えないときにだけ必要です：セルフチェックを 1 回実行すると、どの種類の問題か（ネットワーク不通 / 上流に拒否 / モデル名の廃止 / Key 無効 / レート制限）を教えてくれ、結果をワンタップで開発者に送れます。',
  '这次下的是**完整包**（含运行环境）—— 因为这台手机上还没有，这样装完就能直接打开、不需要联网再补。': '今回ダウンロードするのは**完全パッケージ**（実行環境を含む）です —— この端末にはまだ無いため、インストール後すぐに開けます（追加のダウンロードは不要）。',
  '这次下的是**精简包**（不含运行环境）—— 这台手机上已经有了，所以能省下那份流量。': '今回ダウンロードするのは**軽量パッケージ**（実行環境を含まない）です —— この端末には既にあるため、その分の通信量を節約できます。',
  '这次不提示': '今回は表示しない',
  '这次创作台用哪三个模型': '今回スタジオで使う三つのモデル',
  '这次没有提炼出值得长期记住的内容 —— 这不代表失败，只是这段对话里没有跨会话有用的事实。你也可以自己手写一条。': '今回は長期的に覚えておく価値のある内容は出ませんでした —— 失敗ではなく、この会話にセッションをまたいで役立つ事実が無かっただけです。自分で 1 件書くこともできます。',
  '这次用哪三个模型': '今回使う三つのモデル',
  '这段会话的上下文已经用掉约 {0}（估算）。用「长会话助手」可以把关键信息跟着带到新窗口，接着聊不会断。': 'このセッションはコンテキストを約 {0} 使っています（推定）。「長いセッションの助手」を使うと、要点を新しいウィンドウに引き継いで会話を続けられます。',
  '这段话就是引擎的原话，没加工 —— 发我这份就能直接定位。': 'これはエンジンの原文そのままです。送っていただければ原因を特定できます。',
  '这版引擎没编 Vulkan，只有 CPU 后端': 'このビルドのエンジンには Vulkan がありません（CPU のみ）',
  '这类错误通常过一会儿重试就好。': 'この種のエラーは、少し待って再試行すればたいてい直ります。',
  '这里写的话会进 AGENTS.md，DSH 在**每个新会话的第一个请求前**把它注入模型上下文 —— 与「专家」开关同一条通道。**对已经打开的会话不生效**，要新建一个会话。': 'ここに書いた内容は AGENTS.md に入り、DSH が**新しいセッションの最初のリクエスト前に**モデルコンテキストへ注入します —— 「専門家」スイッチと同じ経路です。**すでに開いているセッションには効きません** —— 新しいセッションを作ってください。',
  '这里只显示你在「专家」页打开开关的专家；它们的角色摘要已写入下面这个文件，DSH 会在新会话的第一个请求前注入模型上下文。': 'ここには「専門家」ページでオンにした専門家だけを表示します。その役割要約は下のファイルに書き込まれ、DSH が新しいセッションの最初のリクエスト前にモデルコンテキストへ注入します。',
  '这里是你录的规则。点「复制」把 JSON 发给别人；别人粘贴到「导入」里就能用。': 'ここに録画したルールが並びます。「コピー」で JSON を共有し、相手は「インポート」に貼り付ければ使えます。',
  '这里汇集了**所有生成过的图片和视频**：「影视」页生成的、以及会话里生成的一起收在这里，不用记是谁生成的。': 'ここには**生成したすべての画像と動画**が集まります —— 「映像」ページで作ったものも、チャットで作ったものも一緒なので、どちらで作ったか覚えていなくて大丈夫です。',
  '这里汇集了所有生成过的图片和视频': '生成した画像と動画はここにまとまります',
  '进行中': '進行中',
  '远程代码执行': 'リモートコード実行',
  '连上了代理，但没取到任何免费模型 —— 上游那条通道可能暂时不可用。': 'プロキシには接続できましたが無料モデルを取得できませんでした — 上流のチャンネルが一時的に使えない可能性があります。',
  '连不上': '接続できません',
  '连不上模型端点。\n可能是：手机网络不通、Base URL 写错，或者你在用「轮换组」而本地代理没起来（回设置页切一下模型就会重新起）；如果你用的是本机模型，多半是引擎刚崩了或被系统回收了 —— 去「设置 → 本地大模型（测试）」重新点一次「启动」。改完重发一次即可。': 'モデルのエンドポイントに接続できません。\n考えられる原因：モバイルネットワークが不通、Base URL の誤り、またはローテーションプールを使っているのにローカルプロキシが起動していない（設定画面でモデルを一度切り替えると再起動します）。オンデバイスモデルの場合は、エンジンが直前にクラッシュしたかシステムに回収された可能性が高いです。「設定 → ローカル大規模モデル（テスト）」で「起動」をもう一度押してください。直したらもう一度送信するだけです。',
  '连不上（网络）': '接続できません（ネットワーク）',
  '连不上：{0}': '接続できません：{0}',
  '连接 DSH': 'DSH に接続',
  '连接 {0}{1}': '{0}{1} に接続',
  '连接中…': '接続中…',
  '连接失败': '接続に失敗しました',
  '连接失败：{0}': '接続に失敗しました：{0}',
  '连接已关闭': '接続が閉じられました',
  '连接已断开': '接続が切断されました',
  '连接日志': '接続ログ',
  '连接被拒绝：桥未启动或端口不对。': '接続が拒否されました：ブリッジが起動していないか、ポートが違います。',
  '连接超时：请确认桥在运行、地址端口正确、手机与电脑在同一网络。': '接続タイムアウト：ブリッジが動作しているか、アドレスとポートが正しいか、スマホとコンピュータが同じネットワークにあるかを確認してください。',
  '连接错误：{0}': '接続エラー：{0}',
  '连通性测试通过（{0}ms）。已把「{1}」的 {2} 个模型登记进来，会话的模型面板里现在就能选。': '接続テストに成功しました（{0}ms）。「{1}」の {2} 個のモデルを登録しました。セッションのモデルパネルですぐに選べます。',
  '连通性测试通过（{0}ms）。已登记 {1} 个模型，会话里现在能选。': '接続テストに成功しました（{0}ms）。{1} 個のモデルを登録しました。セッションですぐに選べます。',
  '适合老花/小屏': '老眼／小さい画面向け',
  '选「保存图片/视频」即可存进相册': '「画像/動画を保存」を選ぶとアルバムに入ります',
  '选一个功能开始。做完点左上角就能回到这里。': '使う機能を選んでください。終わったら左上の矢印でここに戻れます。',
  '选一个视频': '動画を 1 本選ぶ',
  '选一刀': 'カットを選ぶ',
  '选一张图': '画像を選ぶ',
  '选一张开局牌': '開始カードを一枚選ぶ',
  '选了「仅当前工作区」但没有工作目录路径 —— 这条记忆不知道该在哪儿生效。': '「現在のワークスペースのみ」が選ばれましたが、作業ディレクトリのパスがありません —— この記憶は適用先がありません。',
  '选图失败：{0}': '画像の選択に失敗：{0}',
  '选择一条会话': 'セッションを選択',
  '选择壁纸': '壁紙を選択',
  '选择失败': '選択に失敗しました',
  '选择失败：{0}': '選択に失敗しました：{0}',
  '选择文件': 'ファイルを選択',
  '选择文件失败：{0}': 'ファイルを選択できませんでした：{0}',
  '选择模型': 'モデルを選択',
  '选要拼的视频（按顺序）': 'つなげる動画を選ぶ（順番どおり）',
  '选首帧图': '先頭フレームを選ぶ',
  '通了：搜到 {0} 条结果（{1}）。': '通りました：{0} 件の結果（{1}）。',
  '通知': '通知',
  '通透': 'クリア',
  '通道自检': 'チャンネルのセルフチェック',
  '配对失败': 'ペアリングに失敗しました',
  '配对失败：{0}': 'ペアリングに失敗しました：{0}',
  '配对并连接': 'ペアリングして接続',
  '配对码': 'ペアリングコード',
